import Foundation

struct TraditionalOmen: Identifiable {
    let subject: String
    let text: String
    var id: String { subject }
}

struct GuanyinLot: Identifiable {
    let id: Int
    let title: String
    let rank: String
    let palace: String
    let poem: String
    let poeticMeaning: String
    let explanation: String
    let omens: [TraditionalOmen]
    let theme: String
    let story: String

    func reflection(emotion: DrawEmotion) -> String {
        let opening: String
        switch emotion {
        case .sad: opening = "难过不需要被签的等第定义，也不用勉强振作。先让自己歇一会儿，再看看这段文字里有没有对你有帮助的一句。"
        case .grieving: opening = "签文不能解释你的失落，也不会给恢复设期限。你可以慢慢来，愿意时请可信赖的人陪一会儿。"
        case .excited: opening = "先把重要决定放慢一点。传统的上中下签不代表事实或成功率，把感觉与证据分开，再判断是否行动。"
        case .happy: opening = "把好心情留住，也让下一步有事实和准备支撑。签诗可以是一份文化灵感。"
        case .neutral: opening = "不必寻找特别的征兆。把签诗当作一个观察问题的新角度，留下有用的部分即可。"
        }
        return opening
    }

    var modernSections: [(String, String)] {
        GuanyinModernReading.sections(for: self)
    }

    // Common seven-character vernacular recension; not a temple endorsement or a unique canonical edition.
    static let all: [GuanyinLot] = [
        .init(id: 1, title: "钟离成道", rank: "上签", palace: "子宫", poem: "开天辟地作良缘\n吉日良时万物全\n若得此签非小可\n人行忠正帝王宣", poeticMeaning: "此卦盘古初开天地之象。诸事皆吉也。", explanation: "急速兆速。年未值时。观音降笔。先报君知。", omens: [.init(subject: "家宅", text: "祈福"), .init(subject: "自身", text: "秋冬大利"), .init(subject: "求财", text: "秋冬大利"), .init(subject: "交易", text: "成"), .init(subject: "婚姻", text: "成"), .init(subject: "六甲", text: "生男"), .init(subject: "行人", text: "至"), .init(subject: "田蚕", text: "好"), .init(subject: "六畜", text: "好"), .init(subject: "寻人", text: "见"), .init(subject: "公讼", text: "吉"), .init(subject: "失物", text: "东北"), .init(subject: "疾病", text: "设送"), .init(subject: "山坟", text: "吉")], theme: "开端与责任：新机会出现时，先确认承诺和实际准备。", story: "钟离权在民间传说中由将领转而修道，列入八仙。故事常以离开旧身份、重新理解人生寄意。"),
        .init(id: 2, title: "苏秦不第", rank: "下签", palace: "子宫", poem: "鲸鱼未变守江河\n不可升腾更望高\n异日峥嵘身变化\n许君一跃跳龙门", poeticMeaning: "此卦鲸鱼未变之象。凡事忍耐待时也。", explanation: "得忍且忍。得耐且耐。须待时至。功名还在。", omens: [.init(subject: "家宅", text: "不安"), .init(subject: "自身", text: "还愿"), .init(subject: "求财", text: "欠利"), .init(subject: "婚姻", text: "难"), .init(subject: "六甲", text: "作福"), .init(subject: "行人", text: "平安"), .init(subject: "田蚕", text: "吉"), .init(subject: "六畜", text: "不利"), .init(subject: "寻人", text: "见"), .init(subject: "公讼", text: "和"), .init(subject: "移徙", text: "去"), .init(subject: "失物", text: "东南"), .init(subject: "疾病", text: "祈保"), .init(subject: "山坟", text: "吉")], theme: "等待与积累：尚未具备条件时，把时间用于补足基础。", story: "苏秦早年游说未获采用，归家后继续研读与思考，后来以合纵之说见用。故事强调挫折之后的准备。"),
        .init(id: 3, title: "董永遇仙", rank: "下签", palace: "子宫", poem: "临风冒雨去还乡\n正是其身似燕儿\n衔得坭来欲作垒\n到头垒坏复须坭", poeticMeaning: "此卦燕子衔坭之象。凡事劳心费力也。", explanation: "千般用计。晨昏不停。谁知此事。到底劳心。", omens: [.init(subject: "家宅", text: "先凶后吉"), .init(subject: "自身", text: "谨防"), .init(subject: "求财", text: "有"), .init(subject: "疾病", text: "还愿"), .init(subject: "婚姻", text: "不合"), .init(subject: "六甲", text: "男"), .init(subject: "行人", text: "吉"), .init(subject: "蚕畜", text: "利"), .init(subject: "寻人", text: "见"), .init(subject: "公讼", text: "有理"), .init(subject: "移徙", text: "安"), .init(subject: "失物", text: "见"), .init(subject: "交易", text: "成"), .init(subject: "山坟", text: "吉")], theme: "反复与方法：重复受阻时，先检查做法而非只增加投入。", story: "董永卖身葬父、得仙女相助，是民间孝行故事。不同戏曲对夫妻和织锦情节各有铺陈。"),
        .init(id: 4, title: "玉莲会十朋", rank: "上签", palace: "子宫", poem: "千年古镜复重圆\n女再求夫男再婚\n自此门庭重改换\n更添福禄在儿孙", poeticMeaning: "此卦古镜重圆之象。凡事劳心有贵也。", explanation: "淘沙见金。骑龙踏虎。虽是劳心。于中有补。", omens: [.init(subject: "家宅", text: "欠利"), .init(subject: "自身", text: "秋冬旺"), .init(subject: "求财", text: "秋冬旺"), .init(subject: "交易", text: "允"), .init(subject: "婚姻", text: "成"), .init(subject: "六甲", text: "祈保"), .init(subject: "行人", text: "至"), .init(subject: "田蚕", text: "可养"), .init(subject: "六畜", text: "可养"), .init(subject: "寻人", text: "见"), .init(subject: "公讼", text: "不利"), .init(subject: "移徙", text: "守旧"), .init(subject: "失物", text: "迟见"), .init(subject: "疾病", text: "祈福"), .init(subject: "山坟", text: "吉")], theme: "修复与重建：旧事可以重新整理，但需要真实条件与双方意愿。", story: "《荆钗记》写王十朋与钱玉莲分别后遭人离间，玉莲遇险获救，二人历经波折重逢。故事以荆钗为情义的线索。"),
        .init(id: 5, title: "刘晨遇仙", rank: "中签", palace: "丑宫", poem: "一锥凿地要求泉\n努力求之得最难\n无意偶然遇知己\n相逢携手上青天", poeticMeaning: "此卦锥地求泉之象。凡事先难后易也。", explanation: "欲望心事。西方可求。不如莫动。立地可谋。", omens: [.init(subject: "家宅", text: "祈福"), .init(subject: "自身", text: "利"), .init(subject: "求财", text: "利"), .init(subject: "交易", text: "合"), .init(subject: "婚姻", text: "合"), .init(subject: "六甲", text: "安"), .init(subject: "行人", text: "迟"), .init(subject: "田蚕", text: "宜早种"), .init(subject: "六畜", text: "损"), .init(subject: "寻人", text: "见"), .init(subject: "公讼", text: "宜和"), .init(subject: "移徙", text: "吉"), .init(subject: "失物", text: "不见"), .init(subject: "疾病", text: "禳星"), .init(subject: "山坟", text: "吉")], theme: "用力与机缘：努力之外，也给偶然的信息和帮助留空间。", story: "刘晨与阮肇入山采药、遇仙后归来已隔人世岁月，是天台山一带流传的遇仙故事。"),
        .init(id: 6, title: "仁贵遇主", rank: "中签", palace: "丑宫", poem: "投身岩下铜鸟居\n须是还他大丈夫\n拾得营谋谁可得\n通行天地此人无", poeticMeaning: "此卦投岩铜(雕)鸟之象。凡事宜顺吉之兆。", explanation: "食用无余。身清喜贫。待时利乐。权与概人。", omens: [.init(subject: "家宅", text: "不利"), .init(subject: "自身", text: "中吉"), .init(subject: "求财", text: "中吉"), .init(subject: "交易", text: "难"), .init(subject: "婚姻", text: "平平"), .init(subject: "六甲", text: "安"), .init(subject: "行人", text: "近"), .init(subject: "田蚕", text: "早种"), .init(subject: "六畜", text: "损"), .init(subject: "寻人", text: "见"), .init(subject: "移徙", text: "吉"), .init(subject: "失物", text: "见"), .init(subject: "疾病", text: "设送"), .init(subject: "公讼", text: "有理"), .init(subject: "山坟", text: "吉")], theme: "才干与担当：机会需要能力，也需要愿意承担具体责任。", story: "薛仁贵投军、历经考验而受重用，是隋唐故事中常见的成长线索，演义细节与史传有别。"),
        .init(id: 7, title: "苏娘走难", rank: "下签", palace: "丑宫", poem: "奔波阻隔重重险\n带水拖坭去度山\n更望他乡求用事\n千乡万里未回还", poeticMeaning: "此卦拖坭带水之象。凡事守旧则吉也。", explanation: "退身可得。进步为难。只宜守旧。莫望高扳。", omens: [.init(subject: "家宅", text: "不利"), .init(subject: "自身", text: "祈福"), .init(subject: "求财", text: "秋冬吉"), .init(subject: "交易", text: "平平"), .init(subject: "婚姻", text: "祈福"), .init(subject: "六甲", text: "祈福"), .init(subject: "行人", text: "阻"), .init(subject: "田蚕", text: "不利"), .init(subject: "六畜", text: "不利"), .init(subject: "寻人", text: "难"), .init(subject: "公讼", text: "亏"), .init(subject: "移徙", text: "吉"), .init(subject: "失物", text: "不见"), .init(subject: "疾病", text: "作福"), .init(subject: "山坟", text: "不利")], theme: "阻隔与退路：陌生处境中，先照顾安全并保留可回退的选择。", story: "苏娘走难的故事在不同签本中叙述不一，常借漂泊与阻隔表达处境艰难。本版不将传说当作史实。"),
        .init(id: 8, title: "裴度还带", rank: "上签", palace: "丑宫", poem: "茂林松柏正兴旺\n雨雪风霜总莫为\n异日忽然成大用\n功名成就栋梁材", poeticMeaning: "此卦此卦松柏茂林之象。凡事有贵气也。", explanation: "路上亨通。终身有功。田蚕丰熟。家道兴隆。", omens: [.init(subject: "家宅", text: "吉"), .init(subject: "自身", text: "顺利"), .init(subject: "求财", text: "中平"), .init(subject: "交易", text: "旺"), .init(subject: "婚姻", text: "成"), .init(subject: "六甲", text: "男"), .init(subject: "行人", text: "有信"), .init(subject: "田蚕", text: "利"), .init(subject: "六畜", text: "损"), .init(subject: "寻人", text: "至"), .init(subject: "公讼", text: "有理"), .init(subject: "移徙", text: "吉"), .init(subject: "失物", text: "见"), .init(subject: "疾病", text: "安"), .init(subject: "山坟", text: "吉")], theme: "善意与诚信：做可承担的好事，不必以回报作交换。", story: "裴度拾得玉带后归还失主，是民间劝善故事。签题常写作裴度还带，强调不贪意外所得。"),
        .init(id: 9, title: "孔明点将", rank: "中签", palace: "寅宫", poem: "烦君勿作私心事\n此意偏宜说问公\n一片明心光皎洁\n宛如皎月正天心", poeticMeaning: "此卦皎月当空之象。凡事光明通达也。", explanation: "心中正直。理顺法宽。圣无私语。终有分明。", omens: [.init(subject: "家宅", text: "吉"), .init(subject: "自身", text: "顺"), .init(subject: "求财", text: "中平"), .init(subject: "交易", text: "旺"), .init(subject: "婚姻", text: "成"), .init(subject: "六甲", text: "男"), .init(subject: "行人", text: "动"), .init(subject: "田蚕", text: "利"), .init(subject: "六畜", text: "损"), .init(subject: "寻人", text: "至"), .init(subject: "公讼", text: "有理"), .init(subject: "失物", text: "祈福"), .init(subject: "疾病", text: "安"), .init(subject: "山坟", text: "吉")], theme: "统筹与协作：把目标、分工和信息先对齐，再一起行动。", story: "诸葛亮点将的签题取自三国故事，借谋划与调度表现合作。各地签本对具体战役的对应不同。"),
        .init(id: 10, title: "庞涓观阵", rank: "中签", palace: "寅宫", poem: "石藏无价玉和珍\n只管他乡外客寻\n宛如持灯更觅火\n不如收拾枉劳心", poeticMeaning: "此卦持灯觅火之象。凡事待时成就也。", explanation: "姻缘会遇。何事不成。须无限意。眼前是真。", omens: [.init(subject: "家宅", text: "欠利"), .init(subject: "自身", text: "安"), .init(subject: "求财", text: "难"), .init(subject: "交易", text: "难"), .init(subject: "婚姻", text: "合"), .init(subject: "六甲", text: "女"), .init(subject: "行人", text: "动"), .init(subject: "田蚕", text: "秋吉"), .init(subject: "六畜", text: "难养"), .init(subject: "寻人", text: "见"), .init(subject: "公讼", text: "亏"), .init(subject: "移徙", text: "旧安"), .init(subject: "失物", text: "难见"), .init(subject: "疾病", text: "设送"), .init(subject: "山坟", text: "中平")], theme: "观察与核实：看似清楚的局面，也值得再检查关键细节。", story: "庞涓观阵的故事常与孙膑斗智相连，借阵势难辨提醒读者不要只凭表象下判断。"),
        .init(id: 11, title: "书荐姜维", rank: "上签", palace: "寅宫", poem: "欲求胜事可非常\n争奈亲姻日暂忙\n到头竟必成鹿箭\n贵人指引贵人乡", poeticMeaning: "此卦因祸得福之象。凡事营谋吉利也。", explanation: "有意兴变。到底安然。若问用事。只近贵人。", omens: [.init(subject: "家宅", text: "大吉"), .init(subject: "自身", text: "顺利"), .init(subject: "求财", text: "有"), .init(subject: "交易", text: "成"), .init(subject: "婚姻", text: "合"), .init(subject: "六甲", text: "男"), .init(subject: "行人", text: "未至"), .init(subject: "田蚕", text: "中平"), .init(subject: "六畜", text: "中平"), .init(subject: "寻人", text: "见"), .init(subject: "公讼", text: "有理"), .init(subject: "移徙", text: "旺"), .init(subject: "失物", text: "东方"), .init(subject: "疾病", text: "禳星"), .init(subject: "山坟", text: "吉")], theme: "识人与托付：看见他人的能力，也明确自己能承担的部分。", story: "姜维的故事在三国演义中与诸葛亮相遇、受荐重用相连，签题借荐贤寄意。"),
        .init(id: 12, title: "武吉遇师", rank: "上签", palace: "寅宫", poem: "否去泰来咫尺间\n暂交君子出于山\n若逢虎兔佳音信\n立志忙中事即闲", poeticMeaning: "此卦祸中有福之象。凡事先凶后吉也。", explanation: "换麻得丝。击人双足。要见分明。因灾得福。", omens: [.init(subject: "家宅", text: "安"), .init(subject: "自身", text: "吉"), .init(subject: "求财", text: "有"), .init(subject: "交易", text: "宜迟"), .init(subject: "婚姻", text: "成"), .init(subject: "六甲", text: "男"), .init(subject: "行人", text: "未回"), .init(subject: "田蚕", text: "利"), .init(subject: "六畜", text: "慎吉"), .init(subject: "寻人", text: "有信"), .init(subject: "公讼", text: "吉"), .init(subject: "移徙", text: "守"), .init(subject: "失物", text: "见"), .init(subject: "疾病", text: "秋吉"), .init(subject: "山坟", text: "吉")], theme: "相遇与学习：遇到帮助时，主动学习并落实到行动。", story: "武吉在民间封神故事中为樵夫，后来遇姜子牙而得到指点，成为其门下人物。"),
        .init(id: 13, title: "罗通拜帅", rank: "中签", palace: "寅宫", poem: "自小生在富贵家\n眼前万物总奢华\n蒙君赐紫金玉带\n四海声名定可夸", poeticMeaning: "此卦龙门得遇之象。凡事有变大吉也。", explanation: "囚人逢赦。病即安然。龙门得遇。名遍皇都。", omens: [.init(subject: "家宅", text: "祈福"), .init(subject: "自身", text: "祈福"), .init(subject: "求财", text: "冬吉"), .init(subject: "交易", text: "宜迟"), .init(subject: "婚姻", text: "合"), .init(subject: "六甲", text: "女"), .init(subject: "行人", text: "祈保"), .init(subject: "田蚕", text: "中平"), .init(subject: "六畜", text: "中平"), .init(subject: "寻人", text: "见"), .init(subject: "公讼", text: "有理"), .init(subject: "移徙", text: "守旧"), .init(subject: "失物", text: "东方"), .init(subject: "疾病", text: "安"), .init(subject: "山坟", text: "吉")], theme: "历练与信任：承担新角色前，确认能力与支持是否匹配。", story: "罗通拜帅属于说唐故事，写少年将领经历考验、担当军务。签本中也有罗通拜师等异名。"),
        .init(id: 14, title: "子牙弃官", rank: "中签", palace: "卯宫", poem: "宛如仙鹤出樊笼\n脱得樊笼路路通\n南北东西无阻隔\n任君直上九霄宫", poeticMeaning: "此卦仙鹤离笼之象。凡事先凶后吉也。", explanation: "任意无虑。路有亨通。随心所欲。逍遥如人。", omens: [.init(subject: "家宅", text: "不安"), .init(subject: "自身", text: "还愿"), .init(subject: "求财", text: "合"), .init(subject: "交易", text: "合"), .init(subject: "婚姻", text: "合"), .init(subject: "六甲", text: "男"), .init(subject: "行人", text: "见"), .init(subject: "田蚕", text: "秋利"), .init(subject: "六畜", text: "损"), .init(subject: "寻人", text: "阻"), .init(subject: "公讼", text: "宜和"), .init(subject: "移徙", text: "吉"), .init(subject: "失物", text: "东南"), .init(subject: "疾病", text: "设送"), .init(subject: "山坟", text: "吉")], theme: "取舍与自守：不适合的职位或安排，可以认真评估是否离开。", story: "姜子牙弃官的情节见于封神演义体系，常以不愿随同旧秩序而离去表达守志。"),
        .init(id: 15, title: "苏秦得志", rank: "中签", palace: "卯宫", poem: "行人怨日气难吞\n忽有灾事勿近前\n鸟破林巢无所宿\n可寻深处稳安身", poeticMeaning: "此卦鸟鹊离林之象。凡事到底应心也。", explanation: "若人和怨。何时可伸。好言不信。守旧待时。", omens: [.init(subject: "家宅", text: "先凶后吉"), .init(subject: "自身", text: "谨防"), .init(subject: "求财", text: "吉"), .init(subject: "交易", text: "成"), .init(subject: "婚姻", text: "阻滞"), .init(subject: "六甲", text: "男"), .init(subject: "行人", text: "顺"), .init(subject: "田蚕", text: "旺"), .init(subject: "六畜", text: "旺"), .init(subject: "寻人", text: "见"), .init(subject: "公讼", text: "有理"), .init(subject: "移徙", text: "远可"), .init(subject: "失物", text: "难见"), .init(subject: "疾病", text: "还愿"), .init(subject: "山坟", text: "吉")], theme: "转机与准备：被看见的机会，也来自此前持续的积累。", story: "苏秦得志与其早年失意形成对照。故事借合纵见用提醒人们既看机会，也看长期准备。"),
        .init(id: 16, title: "叶梦熊朝帝", rank: "中签", palace: "卯宫", poem: "愁眉思虑暂时开\n启出云霄喜自来\n宛如粪土中藏玉\n良工荐举出尘埃", poeticMeaning: "此卦阴阳和合之象。凡所谋皆吉也。", explanation: "得处无失。损中有益。小人逢凶。君子顺吉。", omens: [.init(subject: "家宅", text: "不利"), .init(subject: "自身", text: "秋冬吉"), .init(subject: "求财", text: "成"), .init(subject: "交易", text: "成"), .init(subject: "婚姻", text: "成"), .init(subject: "六甲", text: "虚惊"), .init(subject: "行人", text: "至"), .init(subject: "田蚕", text: "祈福"), .init(subject: "六畜", text: "平"), .init(subject: "寻人", text: "见"), .init(subject: "公讼", text: "不利"), .init(subject: "移徙", text: "守旧"), .init(subject: "失物", text: "阻"), .init(subject: "疾病", text: "作福"), .init(subject: "山坟", text: "安")], theme: "秩序与职责：在明确规则中发挥能力，减少不必要的消耗。", story: "叶梦熊是明代人物，朝帝的签题借入朝任事表达责任和时机。民间签本对情节有所增饰。"),
        .init(id: 17, title: "望梅止渴", rank: "中签", palace: "卯宫", poem: "莫听闲言说是非\n晨昏只好念弥陀\n若将狂话为真实\n画饼如何止得饥", poeticMeaning: "此卦画饼充饥之象。诸事多虚少实也。", explanation: "心中不定。枉看经文。恰似画饼。食也难吞。", omens: [.init(subject: "家宅", text: "祈福"), .init(subject: "自身", text: "顺利"), .init(subject: "求财", text: "顺利"), .init(subject: "交易", text: "慢"), .init(subject: "婚姻", text: "阻"), .init(subject: "六甲", text: "安"), .init(subject: "行人", text: "迟"), .init(subject: "田蚕", text: "宜早"), .init(subject: "六畜", text: "不利"), .init(subject: "寻人", text: "见"), .init(subject: "公讼", text: "宜和"), .init(subject: "移徙", text: "守旧"), .init(subject: "失物", text: "不见"), .init(subject: "疾病", text: "还愿"), .init(subject: "山坟", text: "吉")], theme: "愿景与现实：鼓励可以缓一时之急，行动仍需真实资源。", story: "望梅止渴说曹操借前方梅林的想象鼓舞行军者。故事提醒期待能支持情绪，却不能替代实际补给。"),
        .init(id: 18, title: "曹国舅为仙", rank: "上签", palace: "卯宫", poem: "金乌西坠兔东升\n日夜循环至古今\n僧道得知无不利\n士农工商各从心", poeticMeaning: "此卦阴阳消长之象。凡事遂意之兆也。(金乌指太阳,玉兔指月亮)", explanation: "心中无事。所作有功。如弓上箭。一发当空。", omens: [.init(subject: "家宅", text: "安"), .init(subject: "自身", text: "吉"), .init(subject: "求财", text: "顺"), .init(subject: "交易", text: "成"), .init(subject: "婚姻", text: "合"), .init(subject: "六甲", text: "男"), .init(subject: "行人", text: "至"), .init(subject: "田蚕", text: "早种"), .init(subject: "六畜", text: "欠利"), .init(subject: "寻人", text: "至"), .init(subject: "公讼", text: "有理"), .init(subject: "移徙", text: "吉"), .init(subject: "失物", text: "迟见"), .init(subject: "疾病", text: "拜送"), .init(subject: "山坟", text: "大吉")], theme: "知止与改变：看见不合适的旧行为，给调整留出空间。", story: "曹国舅在八仙传说中由世俗身份转向修道，故事常借反省与放下表现变化。"),
        .init(id: 19, title: "子仪封王", rank: "中签", palace: "辰宫", poem: "急水滩头放船归\n风波作浪欲何为\n若要安然求稳静\n等待浪静道此危", poeticMeaning: "此卦船行急滩之象。凡事守旧待时也。", explanation: "急水下船。险处待时。若问营谋。尽可施为。", omens: [.init(subject: "家宅", text: "作福"), .init(subject: "自身", text: "作福"), .init(subject: "求财", text: "未成"), .init(subject: "交易", text: "未成"), .init(subject: "婚姻", text: "不就"), .init(subject: "六甲", text: "虚惊"), .init(subject: "行人", text: "至"), .init(subject: "田蚕", text: "吉"), .init(subject: "六畜", text: "损"), .init(subject: "寻人", text: "难"), .init(subject: "公讼", text: "和"), .init(subject: "移徙", text: "守旧"), .init(subject: "失物", text: "难寻"), .init(subject: "疾病", text: "祈福"), .init(subject: "山坟", text: "吉")], theme: "急流与节奏：局势不稳时，减少仓促动作，等信息更清楚。", story: "郭子仪平乱、封汾阳王的事迹衍生许多民间故事。签题与签诗的急水意象并非逐项对应。"),
        .init(id: 20, title: "姜太公遇文王", rank: "中签", palace: "辰宫", poem: "当春久雨喜开晴\n玉兔金乌渐渐明\n旧事消散新事遂\n看看一跳过龙门", poeticMeaning: "此卦久雨初明之象。凡事遂意也。", explanation: "神佛护持。有灾无危。途生平安。到底荣归。", omens: [.init(subject: "家宅", text: "中平"), .init(subject: "自身", text: "祈福"), .init(subject: "求财", text: "未遇"), .init(subject: "交易", text: "待时"), .init(subject: "婚姻", text: "随意"), .init(subject: "六甲", text: "女"), .init(subject: "行人", text: "阻"), .init(subject: "田蚕", text: "阻"), .init(subject: "六畜", text: "阻"), .init(subject: "寻人", text: "迟"), .init(subject: "公讼", text: "和"), .init(subject: "移徙", text: "吉"), .init(subject: "失物", text: "见"), .init(subject: "疾病", text: "禳星"), .init(subject: "山坟", text: "旧吉")], theme: "雨过初晴：环境改善时，先做小而确定的一步。", story: "姜太公在渭水垂钓而遇周文王，是传统贤才见用的故事。签诗借久雨初晴表现处境转变。"),
        .init(id: 21, title: "李旦龙凤配合", rank: "上签", palace: "辰宫", poem: "阴阳道合总由天\n女嫁男婚喜偎然\n但见龙蛇相会合\n熏熏入梦喜团圆", poeticMeaning: "此卦阴阳道合之象。凡事和合大吉也。", explanation: "谋望从心。婚姻孕男。资财进益。更利田蚕。", omens: [.init(subject: "家宅", text: "安"), .init(subject: "自身", text: "利"), .init(subject: "求财", text: "有"), .init(subject: "交易", text: "成"), .init(subject: "婚姻", text: "合"), .init(subject: "六甲", text: "男"), .init(subject: "行人", text: "至"), .init(subject: "田蚕", text: "兴"), .init(subject: "六畜", text: "兴"), .init(subject: "寻人", text: "见"), .init(subject: "公讼", text: "有理"), .init(subject: "移徙", text: "昌盛"), .init(subject: "失物", text: "得见"), .init(subject: "疾病", text: "遇良方"), .init(subject: "山坟", text: "大吉")], theme: "合作与相合：相处是否舒服，要看彼此的沟通与尊重。", story: "李旦与胡凤姣的龙凤配合为民间叙事，常借相逢与团圆表达关系，不等于可据此预测婚配。"),
        .init(id: 22, title: "六郎逢救", rank: "中签", palace: "巳宫", poem: "旱时田里皆枯藁\n谢天甘雨落淋淋\n花果草木皆润泽\n始知一雨值千金", poeticMeaning: "此卦旱逢甘雨之象。凡事难中有救也。", explanation: "田蚕倍熟。命运渐来。病遇良药。行人便回。", omens: [.init(subject: "家宅", text: "祈保"), .init(subject: "自身", text: "安"), .init(subject: "求财", text: "颇有"), .init(subject: "交易", text: "迟"), .init(subject: "婚姻", text: "合"), .init(subject: "六甲", text: "女"), .init(subject: "行人", text: "有阻"), .init(subject: "田蚕", text: "利"), .init(subject: "六畜", text: "利"), .init(subject: "寻人", text: "难"), .init(subject: "公讼", text: "亏"), .init(subject: "移徙", text: "守旧"), .init(subject: "失物", text: "西方"), .init(subject: "疾病", text: "设送（必愈）"), .init(subject: "山坟", text: "安吉")], theme: "及时援手：遇到难处，可以把求助说得更具体。", story: "杨六郎遇险获救的情节来自杨家将故事，常与五台山的兄弟相救相连，借解围寄意。"),
        .init(id: 23, title: "怀德招亲", rank: "中签", palace: "巳宫", poem: "欲扳仙桂入蟾宫\n岂虑天门不任君\n忽遇一般音信好\n人人欢笑领顶花", poeticMeaning: "此卦手扳仙桂之象。凡事必有贵人也。", explanation: "商贾利益。行藏有危。病安讼遂。尽可施为。", omens: [.init(subject: "家宅", text: "欠安"), .init(subject: "自身", text: "作福"), .init(subject: "求财", text: "遂意"), .init(subject: "交易", text: "合"), .init(subject: "婚姻", text: "阻"), .init(subject: "六甲", text: "作福"), .init(subject: "行人", text: "有危"), .init(subject: "田蚕", text: "不利"), .init(subject: "六畜", text: "不利"), .init(subject: "寻人", text: "难"), .init(subject: "公讼", text: "亏"), .init(subject: "移徙", text: "欠吉"), .init(subject: "疾病", text: "安"), .init(subject: "山坟", text: "旧吉")], theme: "消息与核验：收到好消息时，也把条件和下一步确认清楚。", story: "高怀德是北宋开国人物，与皇室联姻的故事成为签题。签诗借桂枝与喜讯表达机会。"),
        .init(id: 24, title: "殷郊遇师", rank: "下签", palace: "巳宫", poem: "不成理论不成家\n水性痴人似落花\n若问君恩须得力\n到头方见事如麻", poeticMeaning: "此卦痴人道塞之象。凡事守旧待时也。", explanation: "是非莫说。必须仔细。心正理直。方免灾危。", omens: [.init(subject: "家宅", text: "不安"), .init(subject: "自身", text: "险"), .init(subject: "求财", text: "阻"), .init(subject: "交易", text: "难"), .init(subject: "婚姻", text: "待时"), .init(subject: "六甲", text: "祈福"), .init(subject: "行人", text: "阻"), .init(subject: "田蚕", text: "多灾"), .init(subject: "六畜", text: "多灾"), .init(subject: "寻人", text: "阻"), .init(subject: "公讼", text: "亏"), .init(subject: "移徙", text: "吉"), .init(subject: "失物", text: "难见"), .init(subject: "疾病", text: "急求神"), .init(subject: "山坟", text: "不吉")], theme: "方向与引导：需要指点时，先说清问题，再选择可靠的信息。", story: "殷郊遇师取自封神故事。不同叙事对其选择和结局有所变化，阅读时宜保留版本意识。"),
        .init(id: 25, title: "李广机智", rank: "中签", palace: "巳宫", poem: "过了忧危事几重\n从今再立永无空\n宽心自有宽心计\n得遇高人立大功", poeticMeaning: "此卦古井逢泉之象。凡事贵人成就也。", explanation: "讼终有理。病得安全。出入求谋。古井逢泉。", omens: [.init(subject: "家宅", text: "平平"), .init(subject: "自身", text: "阻滞"), .init(subject: "求财", text: "阻滞"), .init(subject: "交易", text: "阻滞"), .init(subject: "婚姻", text: "和合"), .init(subject: "六甲", text: "有险"), .init(subject: "行人", text: "阻隔"), .init(subject: "田蚕", text: "不利"), .init(subject: "六畜", text: "不利"), .init(subject: "寻人", text: "阻隔"), .init(subject: "公讼", text: "有理"), .init(subject: "移徙", text: "不合"), .init(subject: "失物", text: "难寻"), .init(subject: "疾病", text: "祈福"), .init(subject: "山坟", text: "不安")], theme: "机敏与分寸：灵活应对，也不要忽略事前准备。", story: "李广的机智事迹在史传与民间叙事中多有流传，签题借临场应变表现勇气和判断。"),
        .init(id: 26, title: "钟馗得道", rank: "中签", palace: "巳宫", poem: "上下传来事转虚\n天边接得一封书\n书中许我功名遂\n直到终时亦是虚", poeticMeaning: "此卦虚名之象。凡事虚多少实宜守旧也。", explanation: "上下心烦。求闲不闲。欲望功名。守旧得安。", omens: [.init(subject: "家宅", text: "祈福"), .init(subject: "自身", text: "安"), .init(subject: "求财", text: "阻"), .init(subject: "交易", text: "不成"), .init(subject: "婚姻", text: "不成"), .init(subject: "六甲", text: "女"), .init(subject: "行人", text: "有信"), .init(subject: "田蚕", text: "半熟"), .init(subject: "六畜", text: "可养"), .init(subject: "寻人", text: "西方"), .init(subject: "公讼", text: "亏"), .init(subject: "移徙", text: "守旧"), .init(subject: "失物", text: "难寻"), .init(subject: "疾病", text: "祈保"), .init(subject: "山坟", text: "吉")], theme: "得失与期待：把愿望放回条件中，不只追逐外来的许诺。", story: "钟馗得道的传说结合科举失意与驱邪形象。签诗与人物故事的对应，各地版本有差异。"),
        .init(id: 27, title: "刘基谏主", rank: "中签", palace: "午宫", poem: "一谋一用一番书\n虑后思前不敢为\n时到贵人相助力\n如山壁立可安居", poeticMeaning: "此卦屋好墙壁之象。凡事稳当无险也。", explanation: "改旧成新。寒花遇春。从前阻滞。今得称心。", omens: [.init(subject: "家宅", text: "安"), .init(subject: "自身", text: "吉"), .init(subject: "求财", text: "有"), .init(subject: "交易", text: "难"), .init(subject: "婚姻", text: "阻"), .init(subject: "六甲", text: "女"), .init(subject: "行人", text: "迟"), .init(subject: "田蚕", text: "熟"), .init(subject: "六畜", text: "利"), .init(subject: "寻人", text: "迟"), .init(subject: "公讼", text: "宜和"), .init(subject: "移徙", text: "吉"), .init(subject: "失物", text: "无踪"), .init(subject: "疾病", text: "延安"), .init(subject: "山坟", text: "守旧大吉")], theme: "进言与倾听：表达不同意见时，先核实事实，再说明理由。", story: "刘基辅佐明太祖的事迹衍生许多谏主故事，签题常借忠言与判断表现处世分寸。"),
        .init(id: 28, title: "李后寻包公", rank: "中签", palace: "午宫", poem: "东边月上正蝉娟\n顷刻云遮亦暗存\n或有圆时还有缺\n更言非者亦闲言", poeticMeaning: "此卦月被云遮之象。凡事昏迷未定也。", explanation: "浮云遮月。不须疑惑。等待云收。便见收获。", omens: [.init(subject: "家宅", text: "不安"), .init(subject: "自身", text: "祈保"), .init(subject: "求财", text: "阻"), .init(subject: "交易", text: "吉"), .init(subject: "婚姻", text: "不合"), .init(subject: "六甲", text: "有惊"), .init(subject: "行人", text: "滞"), .init(subject: "田蚕", text: "不利"), .init(subject: "六畜", text: "不利"), .init(subject: "寻人", text: "难"), .init(subject: "公讼", text: "亏"), .init(subject: "移徙", text: "守旧"), .init(subject: "失物", text: "西方"), .init(subject: "疾病", text: "难痊"), .init(subject: "山坟", text: "改")], theme: "寻找与求助：重要事情需要可靠的渠道和清楚的说明。", story: "李后寻包公与狸猫换太子的戏曲故事有关，借求助、公正与身份昭雪寄意。"),
        .init(id: 29, title: "赵子龙救阿斗", rank: "中签", palace: "午宫", poem: "宝剑出匣耀光明\n在匣全然不惹尘\n今得贵人携出现\n有威有势众人钦", poeticMeaning: "此卦宝剑出匣之象。凡事有威有势也。", explanation: "宝剑出匣。光辉万里。贵人指引。无不观美。", omens: [.init(subject: "家宅", text: "祈福"), .init(subject: "自身", text: "吉"), .init(subject: "求财", text: "利"), .init(subject: "交易", text: "成"), .init(subject: "婚姻", text: "好"), .init(subject: "六甲", text: "女"), .init(subject: "行人", text: "滞"), .init(subject: "田蚕", text: "宜早"), .init(subject: "六畜", text: "损"), .init(subject: "寻人", text: "见"), .init(subject: "公讼", text: "和"), .init(subject: "移徙", text: "兴"), .init(subject: "失物", text: "南方"), .init(subject: "疾病", text: "还旧愿"), .init(subject: "山坟", text: "吉")], theme: "勇气与保护：承担责任时，也照顾需要保护的人和边界。", story: "赵云救阿斗是三国演义中的著名情节，写战乱中护送幼主，突出担当与临危应变。"),
        .init(id: 30, title: "棋盘大会", rank: "中签", palace: "午宫", poem: "劝君切莫向他求\n似鹤飞来暗箭投\n若去采薪蛇在草\n恐遭毒口也忧愁", poeticMeaning: "此卦安份守己之象。凡事小心谨防也。", explanation: "闭口合齿。他事莫理。若有亏心。到头害己。", omens: [.init(subject: "家宅", text: "安"), .init(subject: "自身", text: "平平"), .init(subject: "求财", text: "待时"), .init(subject: "交易", text: "滞"), .init(subject: "婚姻", text: "未许"), .init(subject: "六甲", text: "虚惊"), .init(subject: "行人", text: "阻隔"), .init(subject: "田蚕", text: "不利"), .init(subject: "六畜", text: "不利"), .init(subject: "寻人", text: "阻隔"), .init(subject: "公讼", text: "莫兴"), .init(subject: "移徙", text: "守旧"), .init(subject: "失物", text: "不见"), .init(subject: "疾病", text: "难痊"), .init(subject: "山坟", text: "大吉")], theme: "相逢与磨合：不同想法聚在一起，需要共同规则。", story: "棋盘大会属于民间演义题材，人物与情节在签本间不尽相同。签诗着重于相遇与局面变化。"),
        .init(id: 31, title: "佛印会东坡", rank: "中签", palace: "未宫", poem: "清闲无忧静处坐\n饱后喝茶时坐卧\n放下身心不用忙\n必定不招冤与祸", poeticMeaning: "此卦守旧安然之象。凡事时待时则吉也。", explanation: "守旧安然。叩问神仙。直待时来。事亦偶然。", omens: [.init(subject: "家宅", text: "祈保"), .init(subject: "自身", text: "安"), .init(subject: "求财", text: "守待"), .init(subject: "交易", text: "宜迟"), .init(subject: "婚姻", text: "合"), .init(subject: "六甲", text: "女"), .init(subject: "行人", text: "至"), .init(subject: "田蚕", text: "秋熟"), .init(subject: "六畜", text: "稳"), .init(subject: "寻人", text: "难"), .init(subject: "公讼", text: "和"), .init(subject: "移徙", text: "吉"), .init(subject: "失物", text: "虚"), .init(subject: "疾病", text: "设送"), .init(subject: "山坟", text: "吉")], theme: "放下成见：换一个角度，可能看见原先遗漏的部分。", story: "佛印与苏东坡的问答故事广为流传，常以机锋与幽默提醒人们反观自己的判断。"),
        .init(id: 32, title: "刘备求贤", rank: "中签", palace: "未宫", poem: "前程杳杳定无疑\n石中藏玉有谁知\n一朝良匠分明剖\n始觉安然碧玉期", poeticMeaning: "此卦剖石见玉之象。凡事着力成功也。", explanation: "宝在石中。异人少知。直待分明。尽可施为。", omens: [.init(subject: "家宅", text: "平平"), .init(subject: "自身", text: "安"), .init(subject: "求财", text: "劳力"), .init(subject: "交易", text: "阻"), .init(subject: "婚姻", text: "成"), .init(subject: "六甲", text: "虚"), .init(subject: "行人", text: "杳"), .init(subject: "田蚕", text: "晚成"), .init(subject: "六畜", text: "旺"), .init(subject: "寻人", text: "见"), .init(subject: "公讼", text: "惊"), .init(subject: "移徙", text: "改"), .init(subject: "失物", text: "西方"), .init(subject: "疾病", text: "欠安"), .init(subject: "山坟", text: "改向吉")], theme: "求贤与诚意：需要合作时，把尊重落实为具体行动。", story: "刘备求贤常指三顾茅庐，写反复拜访诸葛亮、商议志向，借诚意和相互选择寄意。"),
        .init(id: 33, title: "咬金聘仁贵", rank: "中签", palace: "未宫", poem: "内藏无价宝和珍\n得玉何须外界寻\n不如等待高人识\n宽心犹且更宽心", poeticMeaning: "此卦藏玉外觅之象。凡事待时可也。", explanation: "内藏金玉。何必外寻。遇贵指引。不须劳心。", omens: [.init(subject: "家宅", text: "祈保"), .init(subject: "自身", text: "安"), .init(subject: "求财", text: "守待"), .init(subject: "交易", text: "迟"), .init(subject: "婚姻", text: "就"), .init(subject: "六甲", text: "男"), .init(subject: "行人", text: "阻"), .init(subject: "田蚕", text: "半熟"), .init(subject: "六畜", text: "旺"), .init(subject: "寻人", text: "劳"), .init(subject: "公讼", text: "搁"), .init(subject: "移徙", text: "吉"), .init(subject: "失物", text: "北方"), .init(subject: "疾病", text: "遇良医"), .init(subject: "山坟", text: "宜改")], theme: "识才与机会：评价一个人，需要看实际能力与行动。", story: "程咬金与薛仁贵的演义故事常围绕识才、荐才展开，签题借被发现的能力表达转机。"),
        .init(id: 34, title: "桃园结义", rank: "中签", palace: "未宫", poem: "行藏出入礼义恭\n言必忠良信必聪\n心不了然且静澈\n光明红日正当空", poeticMeaning: "此卦红日当空正照之象。凡事遂意也。", explanation: "心中无事。秋水澄清。不须疑惑。事自然成。", omens: [.init(subject: "家宅", text: "清吉"), .init(subject: "自身", text: "安"), .init(subject: "求财", text: "虚"), .init(subject: "交易", text: "难"), .init(subject: "婚姻", text: "合"), .init(subject: "六甲", text: "有险"), .init(subject: "行人", text: "阻"), .init(subject: "田蚕", text: "不利"), .init(subject: "六畜", text: "衰"), .init(subject: "寻人", text: "滞"), .init(subject: "公讼", text: "亏"), .init(subject: "移徙", text: "守旧"), .init(subject: "失物", text: "虚"), .init(subject: "疾病", text: "设送"), .init(subject: "山坟", text: "大吉")], theme: "承诺与同行：好的关系也需要明确责任和彼此守信。", story: "刘备、关羽、张飞桃园结义的情节见于三国演义，象征共同志向和相互承担。"),
        .init(id: 35, title: "唐僧取经", rank: "中签", palace: "申宫", poem: "衣冠重整旧家风\n道是无穹却有功\n扫却当途荆棘刺\n三人约议再和同", poeticMeaning: "此卦衣冠重整之象。凡事先难后易也。", explanation: "不用忧疑。自有佳期。若问前程。前路可宜。", omens: [.init(subject: "家宅", text: "乱"), .init(subject: "自身", text: "吉"), .init(subject: "求财", text: "好"), .init(subject: "交易", text: "利"), .init(subject: "婚姻", text: "阻"), .init(subject: "六甲", text: "惊"), .init(subject: "行人", text: "至"), .init(subject: "田蚕", text: "不利"), .init(subject: "六畜", text: "兴"), .init(subject: "寻人", text: "至"), .init(subject: "公讼", text: "有理"), .init(subject: "移徙", text: "安"), .init(subject: "失物", text: "迟见"), .init(subject: "疾病", text: "祈福"), .init(subject: "山坟", text: "宜旧")], theme: "远行与耐心：长路可以拆成阶段，也需要补给与伙伴。", story: "唐僧取经的故事以西行历险为线索，借反复磨炼表现坚持、协作和目标。"),
        .init(id: 36, title: "湘子遇宾", rank: "中签", palace: "申宫", poem: "眼前病讼不须忧\n满地资财尽可求\n恰似猿猴金锁脱\n自归山洞去来游", poeticMeaning: "此卦猿猴脱锁之象。凡事先难后易也。", explanation: "脱除了事。且自宽心。待得时来。堪寻正路。", omens: [.init(subject: "家宅", text: "不安"), .init(subject: "自身", text: "安"), .init(subject: "求财", text: "大利"), .init(subject: "交易", text: "待时"), .init(subject: "婚姻", text: "未成"), .init(subject: "六甲", text: "祈保"), .init(subject: "行人", text: "至"), .init(subject: "田蚕", text: "十足"), .init(subject: "六畜", text: "平"), .init(subject: "寻人", text: "至"), .init(subject: "公讼", text: "有理"), .init(subject: "移徙", text: "吉"), .init(subject: "失物", text: "远"), .init(subject: "疾病", text: "欠安"), .init(subject: "山坟", text: "吉")], theme: "启发与选择：新的观点可以参考，决定仍需自己承担。", story: "韩湘子与吕洞宾相遇的传说属于八仙故事，常借点化和学习表达观念改变。"),
        .init(id: 37, title: "李靖归山", rank: "中签", palace: "申宫", poem: "欲待身安运泰时\n风中灯烛不相宜\n不如收拾深堂坐\n庶免光摇静处明", poeticMeaning: "此卦风摇灯烛之象。凡事守常则吉也。", explanation: "静处安身。待命守时。动惹非福。守旧无疑。", omens: [.init(subject: "家宅", text: "守旧"), .init(subject: "自身", text: "平平"), .init(subject: "求财", text: "有"), .init(subject: "交易", text: "难"), .init(subject: "婚姻", text: "不合"), .init(subject: "六甲", text: "祈保"), .init(subject: "行人", text: "有信"), .init(subject: "田蚕", text: "秋熟"), .init(subject: "六畜", text: "安"), .init(subject: "寻人", text: "见"), .init(subject: "公讼", text: "和"), .init(subject: "移徙", text: "守旧"), .init(subject: "疾病", text: "禳星"), .init(subject: "山坟", text: "勿改")], theme: "功成与知退：何时收束投入，也值得提前思考。", story: "李靖归山的民间故事有不同版本，常借立功之后退隐表达功业与生活的取舍。"),
        .init(id: 38, title: "何文秀遇难", rank: "下签", palace: "申宫", poem: "月照天书静处期\n忽遭云雾又昏迷\n宽心祈待云霞散\n此时更改好施为", poeticMeaning: "此卦云雾遮月之象。凡事未遂守旧也。", explanation: "家道忧凶。人口有灾。祈福保庆。犹恐破财。", omens: [.init(subject: "家宅", text: "不安"), .init(subject: "自身", text: "祈保"), .init(subject: "求财", text: "难"), .init(subject: "交易", text: "待时"), .init(subject: "婚姻", text: "难合"), .init(subject: "六甲", text: "虚惊"), .init(subject: "行人", text: "阻"), .init(subject: "田蚕", text: "损"), .init(subject: "六畜", text: "损"), .init(subject: "寻人", text: "遇"), .init(subject: "公讼", text: "和"), .init(subject: "移徙", text: "安"), .init(subject: "失物", text: "虚"), .init(subject: "疾病", text: "延安"), .init(subject: "山坟", text: "宜修")], theme: "误解与澄清：遇到不公时，保留事实并寻求合适帮助。", story: "何文秀的故事见于越剧和地方戏，写读书人蒙冤后获得澄清，情节因剧种而异。"),
        .init(id: 39, title: "姜女寻夫", rank: "下签", palace: "酉宫", poem: "天边消息实难思\n切莫多心望强求\n若把石头磨作镜\n曾知枉费己工夫", poeticMeaning: "此卦守常安静之象。凡事守己则吉也。", explanation: "千般用计。枉费功夫。不如守旧。着甚来由。.", omens: [.init(subject: "家宅", text: "安"), .init(subject: "自身", text: "提防"), .init(subject: "求财", text: "平平"), .init(subject: "交易", text: "阻"), .init(subject: "婚姻", text: "不合"), .init(subject: "六甲", text: "女"), .init(subject: "行人", text: "动"), .init(subject: "田蚕", text: "利"), .init(subject: "六畜", text: "损"), .init(subject: "寻人", text: "难"), .init(subject: "公讼", text: "亏"), .init(subject: "移徙", text: "平"), .init(subject: "失物", text: "空"), .init(subject: "疾病", text: "送。安"), .init(subject: "山坟", text: "大吉")], theme: "思念与现实：情感需要被照顾，寻找也要顾及自身安全。", story: "孟姜女寻夫是广泛流传的民间故事，表达离别与思念。不同地区对长城和哭城情节有不同讲述。"),
        .init(id: 40, title: "武则天登位", rank: "中签", palace: "酉宫", poem: "红轮西坠兔东升\n阴长阳消百事亭\n若是女人宜望用\n增添财禄福其心", poeticMeaning: "此卦阴长阳消之象。凡事先难后易也。", explanation: "阴利女人。不宜男子。若是求谋。先凶后吉。", omens: [.init(subject: "家宅", text: "不利"), .init(subject: "自身", text: "祈福"), .init(subject: "求财", text: "守待"), .init(subject: "交易", text: "吉"), .init(subject: "婚姻", text: "不合"), .init(subject: "六甲", text: "虚"), .init(subject: "行人", text: "阻"), .init(subject: "田蚕", text: "旺"), .init(subject: "六畜", text: "旺"), .init(subject: "寻人", text: "隔"), .init(subject: "公讼", text: "亏"), .init(subject: "移徙", text: "大吉"), .init(subject: "失物", text: "空"), .init(subject: "疾病", text: "有惊"), .init(subject: "山坟", text: "大吉")], theme: "新局与责任：角色改变之后，更需要清楚的规则和反馈。", story: "武则天登位的历史衍生多种民间讲述。签题借身份变化表达局面转折，不作个人命运类比。"),
        .init(id: 41, title: "董卓收吕布", rank: "中签", palace: "酉宫", poem: "无限好言君记取\n却为认贼将作子\n莫贪眼下有些甜\n更虑他年前样思", poeticMeaning: "此卦认贼作子之象。凡事认真防假。", explanation: "只这一着。君子莫错。牢记在心。不生寂寞。", omens: [.init(subject: "家宅", text: "不安"), .init(subject: "自身", text: "平常"), .init(subject: "求财", text: "守待"), .init(subject: "交易", text: "难"), .init(subject: "婚姻", text: "未合"), .init(subject: "六甲", text: "男惊"), .init(subject: "行人", text: "至"), .init(subject: "田蚕", text: "半熟"), .init(subject: "六畜", text: "安"), .init(subject: "寻人", text: "至"), .init(subject: "公讼", text: "宜和"), .init(subject: "移徙", text: "祈保"), .init(subject: "疾病", text: "禳星"), .init(subject: "山坟", text: "中平")], theme: "利益与边界：合作前先确认价值和责任是否一致。", story: "董卓收吕布是三国故事中的情节，写利益、依附与关系变化，提醒读者留意信任的基础。"),
        .init(id: 42, title: "目莲救母", rank: "上签", palace: "酉宫", poem: "君皇圣后总为恩\n复待祈禳无损增\n一切有情皆受用\n人间天上得期亨", poeticMeaning: "此卦天垂恩泽之象。凡事成就大吉也。", explanation: "天皇降恩。始终莫忘。晨昏礼佛。可宜烧香。", omens: [.init(subject: "家宅", text: "祈福"), .init(subject: "自身", text: "冬吉"), .init(subject: "求财", text: "未有"), .init(subject: "交易", text: "成"), .init(subject: "婚姻", text: "中吉"), .init(subject: "六甲", text: "平安"), .init(subject: "行人", text: "动"), .init(subject: "田蚕", text: "中平"), .init(subject: "六畜", text: "中平"), .init(subject: "寻人", text: "见"), .init(subject: "公讼", text: "胜"), .init(subject: "移徙", text: "守旧"), .init(subject: "失物", text: "空"), .init(subject: "疾病", text: "解"), .init(subject: "山坟", text: "安")], theme: "关怀与行动：惦念亲人时，也可以从当下能做的一件事开始。", story: "目莲救母是佛教故事在民间戏曲中的重要题材，承载孝亲与慈悲的文化意象。"),
        .init(id: 43, title: "行者得道", rank: "上签", palace: "戌宫", poem: "天地变通万物全\n自营自养自安然\n生罗万象皆精彩\n事事如心谢圣贤", poeticMeaning: "此卦大地交泰之象。凡事大吉无危也。", explanation: "天生万物。谋望皆通。福德相助。瑞气匆匆。", omens: [.init(subject: "家宅", text: "吉"), .init(subject: "自身", text: "安"), .init(subject: "求财", text: "有"), .init(subject: "交易", text: "利"), .init(subject: "婚姻", text: "合"), .init(subject: "六甲", text: "男"), .init(subject: "行人", text: "有阻"), .init(subject: "田蚕", text: "中平"), .init(subject: "六畜", text: "中平"), .init(subject: "寻人", text: "见"), .init(subject: "公讼", text: "胜"), .init(subject: "移徙", text: "利"), .init(subject: "失物", text: "东西"), .init(subject: "疾病", text: "禳星"), .init(subject: "山坟", text: "东西吉")], theme: "历练与觉察：把经历转为理解，不必急着证明已经改变。", story: "行者得道常借取经故事中的孙悟空寄意，各地签本也有不同人物对应，重点在经历与修持。"),
        .init(id: 44, title: "姜维邓艾斗阵", rank: "中签", palace: "戌宫", poem: "棋逢敌手着相宜\n黑白盘中未决时\n皆因一着知胜败\n须教自有好推宜", poeticMeaning: "此卦棋逢敌手之象。凡事用机关则吉也。", explanation: "欲求心事。恰如围棋。到底胜利。宜用心机。", omens: [.init(subject: "家宅", text: "大利"), .init(subject: "自身", text: "平稳"), .init(subject: "求财", text: "遂"), .init(subject: "交易", text: "利"), .init(subject: "婚姻", text: "未合"), .init(subject: "六甲", text: "女"), .init(subject: "行人", text: "阻"), .init(subject: "田蚕", text: "平"), .init(subject: "六畜", text: "损"), .init(subject: "寻人", text: "阻"), .init(subject: "公讼", text: "宜和"), .init(subject: "移徙", text: "守旧"), .init(subject: "失物", text: "空"), .init(subject: "疾病", text: "祈保"), .init(subject: "山坟", text: "守旧")], theme: "对局与预案：不要只看一条发展路线，也想想对方的条件。", story: "姜维与邓艾斗阵的故事取自三国演义，借攻防与谋划提醒观察局势和资源。"),
        .init(id: 45, title: "仁宗认母", rank: "上签", palace: "戌宫", poem: "温柔自古胜刚强\n积善之门大吉昌\n若是有人占此卦\n宛如正渴遇琼浆", poeticMeaning: "此卦积善温柔之象。凡事贵人和合也。", explanation: "天地有感。应验非常。佛神护佑。得之莫忘。", omens: [.init(subject: "家宅", text: "吉"), .init(subject: "自身", text: "安"), .init(subject: "求财", text: "遂"), .init(subject: "交易", text: "利"), .init(subject: "婚姻", text: "合"), .init(subject: "六甲", text: "男"), .init(subject: "行人", text: "阻"), .init(subject: "田蚕", text: "秋利"), .init(subject: "六畜", text: "中平"), .init(subject: "寻人", text: "见"), .init(subject: "公讼", text: "胜"), .init(subject: "移徙", text: "利"), .init(subject: "失物", text: "东方"), .init(subject: "疾病", text: "祈福"), .init(subject: "山坟", text: "东西向吉")], theme: "亲情与辨认：澄清重要事情，需要耐心核实与合适渠道。", story: "仁宗认母与李后故事在地方戏中相连，借亲人重逢、公道昭雪表达恢复关系。"),
        .init(id: 46, title: "渭水钓鱼", rank: "中签", palace: "戌宫", poem: "劝君耐守旧生涯\n把定心肠勿起歹\n直待有人轻着力\n枯枝老树再生花", poeticMeaning: "此卦枯木生花之象。凡事自有成就也。", explanation: "守旧守旧。事自成就。动则多殃。静则无咎。", omens: [.init(subject: "家宅", text: "安"), .init(subject: "自身", text: "吉"), .init(subject: "求财", text: "待时"), .init(subject: "交易", text: "成"), .init(subject: "婚姻", text: "就"), .init(subject: "六甲", text: "生女"), .init(subject: "行人", text: "阻"), .init(subject: "田蚕", text: "五分"), .init(subject: "六畜", text: "难"), .init(subject: "寻人", text: "杳"), .init(subject: "公讼", text: "吉"), .init(subject: "移徙", text: "守旧"), .init(subject: "失物", text: "空"), .init(subject: "疾病", text: "求福"), .init(subject: "山坟", text: "吉")], theme: "耐心与相遇：等待时机时，也保持自身的学习与准备。", story: "渭水钓鱼写姜子牙在渭水等待见用、与文王相遇，是传统贤者遇主的意象。"),
        .init(id: 47, title: "梁灏登科", rank: "上签", palace: "亥宫", poem: "锦上添花色愈鲜\n运来禄马喜双全\n时人莫恨功名晚\n一举登科四海传", poeticMeaning: "此卦锦上添花之象。凡事大吉大利也。", explanation: "守旧变新。运至功成。遂平生志。尽皆是命。", omens: [.init(subject: "家宅", text: "祈保"), .init(subject: "自身", text: "安"), .init(subject: "求财", text: "利"), .init(subject: "交易", text: "阻"), .init(subject: "婚姻", text: "合"), .init(subject: "六甲", text: "生男"), .init(subject: "行人", text: "迟"), .init(subject: "田蚕", text: "八分"), .init(subject: "六畜", text: "平"), .init(subject: "寻人", text: "至"), .init(subject: "公讼", text: "宜和"), .init(subject: "移徙", text: "吉"), .init(subject: "失物", text: "西北"), .init(subject: "疾病", text: "作福"), .init(subject: "山坟", text: "利")], theme: "积累与迟成：达成目标的节奏不止一种，关注可持续投入。", story: "梁灏登科的民间故事以年长后应试成名寄意，具体年龄与情节在史传、传说中有别。"),
        .init(id: 48, title: "韩信挂帅", rank: "中签", palace: "亥宫", poem: "昆鸟秋来化作鹏\n好游快乐喜飞腾\n翱翔万里云霄去\n余外诸禽总不能", poeticMeaning: "此卦昆鹏兴变之象。凡事有变动大吉。", explanation: "昆鸟化鹏。万禽不能。桂香一折。福禄自增。", omens: [.init(subject: "家宅", text: "利"), .init(subject: "自身", text: "吉"), .init(subject: "求财", text: "秋旺"), .init(subject: "交易", text: "迟"), .init(subject: "婚姻", text: "不合"), .init(subject: "六甲", text: "安"), .init(subject: "行人", text: "阻滞"), .init(subject: "田蚕", text: "中平"), .init(subject: "六畜", text: "春利"), .init(subject: "寻人", text: "见"), .init(subject: "公讼", text: "胜"), .init(subject: "移徙", text: "守旧"), .init(subject: "失物", text: "西"), .init(subject: "山坟", text: "安"), .init(subject: "疾病", text: "祈保")], theme: "信任与任用：新的责任需要明确授权，也需要实际能力。", story: "韩信挂帅的故事常与萧何荐贤相连，表达才干被看见以及职责的分配。"),
        .init(id: 49, title: "王祥求鲤", rank: "中签", palace: "亥宫", poem: "鲲鸟秋来化作鹏\n好游快乐喜飞腾\n翱翔万里云霄去\n余外诸禽总不能", poeticMeaning: "此卦水结成冰之象。凡事不用枉求也。", explanation: "水结成冰。冰消成水。若是营谋。到底如是。", omens: [.init(subject: "家宅", text: "不安"), .init(subject: "自身", text: "祈保"), .init(subject: "求财", text: "难"), .init(subject: "交易", text: "阻"), .init(subject: "婚姻", text: "不合"), .init(subject: "六甲", text: "险"), .init(subject: "行人", text: "迟"), .init(subject: "田蚕", text: "亏"), .init(subject: "六畜", text: "损"), .init(subject: "寻人", text: "见"), .init(subject: "公讼", text: "和"), .init(subject: "移徙", text: "守旧"), .init(subject: "失物", text: "空"), .init(subject: "疾病", text: "难痊"), .init(subject: "山坟", text: "大吉")], theme: "关怀与界限：照顾亲人时，选择合适且安全的做法。", story: "王祥求鲤属于传统孝行故事。本版将其作为文学意象阅读，不鼓励模仿冰水等危险行为。"),
        .init(id: 50, title: "陶朱归五湖", rank: "中签", palace: "亥宫", poem: "五湖四海任君行\n高挂帆蓬自在撑\n若得顺风随即至\n满船宝贝喜层层", poeticMeaning: "此卦顺风撑船之象。凡事皆顺大吉也。", explanation: "自在休悠。不须着力。财禄重重。无不欣美。", omens: [.init(subject: "家宅", text: "利"), .init(subject: "自身", text: "吉"), .init(subject: "求财", text: "利西"), .init(subject: "交易", text: "宜迟"), .init(subject: "婚姻", text: "不合"), .init(subject: "六甲", text: "安"), .init(subject: "行人", text: "阻"), .init(subject: "田蚕", text: "秋利"), .init(subject: "六畜", text: "春旺"), .init(subject: "寻人", text: "至"), .init(subject: "公讼", text: "亏"), .init(subject: "移徙", text: "守旧"), .init(subject: "失物", text: "西方"), .init(subject: "疾病", text: "解"), .init(subject: "山坟", text: "南利")], theme: "收束与生活：达到阶段目标后，也可以重新安排自己想过的日子。", story: "陶朱公即范蠡的民间形象，故事常写功成之后归于五湖，以进退取舍寄意。"),
        .init(id: 51, title: "孔明入川", rank: "上签", palace: "子宫", poem: "夏日炎天日最长\n人人愁热闷非常\n天地也解知人意\n熏风拂拂自然凉", poeticMeaning: "此卦人人愁热之象。凡事随心从意也。", explanation: "进退莫疑。自有佳期。营谋用度。不须妄为。", omens: [.init(subject: "家宅", text: "祈福"), .init(subject: "自身", text: "谨防"), .init(subject: "求财", text: "秋吉"), .init(subject: "交易", text: "平常"), .init(subject: "婚姻", text: "合"), .init(subject: "六甲", text: "生男"), .init(subject: "行人", text: "动"), .init(subject: "田蚕", text: "损"), .init(subject: "六畜", text: "平"), .init(subject: "寻人", text: "见"), .init(subject: "公讼", text: "吉"), .init(subject: "移徙", text: "旧"), .init(subject: "失物", text: "北方"), .init(subject: "疾病", text: "还愿"), .init(subject: "山坟", text: "吉")], theme: "规划与行进：大目标需要分段推进，并随反馈调整。", story: "诸葛亮入川的签题取意三国故事，借行程、谋划与协作表现开展新局面的准备。"),
        .init(id: 52, title: "太白醉捞明月", rank: "中签", palace: "子宫", poem: "水中捞月费功夫\n费尽功夫却又无\n莫说闲言并乱语\n枉劳心力强身孤", poeticMeaning: "此卦贪求费力之象。凡事劳心费力也", explanation: "言语难思。费力劳心。宅中忧恼。待遇贵人。", omens: [.init(subject: "家宅", text: "不安"), .init(subject: "自身", text: "欠吉"), .init(subject: "求财", text: "中平"), .init(subject: "交易", text: "难"), .init(subject: "婚姻", text: "未就"), .init(subject: "六甲", text: "祈保"), .init(subject: "行人", text: "有灾"), .init(subject: "田蚕", text: "五分"), .init(subject: "六畜", text: "衰"), .init(subject: "寻人", text: "凶"), .init(subject: "公讼", text: "和"), .init(subject: "移徙", text: "平常"), .init(subject: "失物", text: "空"), .init(subject: "山坟", text: "吉"), .init(subject: "疾病", text: "祈保")], theme: "虚影与事实：看起来可得的东西，也需要确认是否真实。", story: "太白醉捞明月是围绕李白形成的文学传说，借水中月的意象表达追逐幻象，不作其真实死因的说明。"),
        .init(id: 53, title: "刘备招亲", rank: "中签", palace: "子宫", poem: "失意反成得意时\n龙呤虎啸两相宜\n青天自有通霄路\n许我功名再有期", poeticMeaning: "此卦龙吟虎啸之象。凡事顺意有望也。", explanation: "教去即去。教住即住。自有亨通。到头必利。", omens: [.init(subject: "家宅", text: "不安"), .init(subject: "自身", text: "欠吉"), .init(subject: "求财", text: "中平"), .init(subject: "交易", text: "难"), .init(subject: "婚姻", text: "成就"), .init(subject: "六甲", text: "祈保"), .init(subject: "行人", text: "至"), .init(subject: "田蚕", text: "五分"), .init(subject: "六畜", text: "损"), .init(subject: "寻人", text: "至"), .init(subject: "公讼", text: "和"), .init(subject: "移徙", text: "吉"), .init(subject: "失物", text: "见"), .init(subject: "疾病", text: "安"), .init(subject: "山坟", text: "吉")], theme: "相遇与沟通：靠近之前，确认双方的意愿和现实条件。", story: "刘备招亲取自三国演义中与孙尚香联姻的故事，写关系、谋略和局势相互牵动。"),
        .init(id: 54, title: "马超追曹", rank: "下签", palace: "子宫", poem: "梦中得宝醒来无\n自谓南山只是锄\n若问婚姻并问病\n别寻条路为相扶", poeticMeaning: "此卦梦中得宝之象。凡事枉费心力也。", explanation: "物在水中。形影长短。皆有分定。不用商量。", omens: [.init(subject: "家宅", text: "欠安"), .init(subject: "自身", text: "谨防"), .init(subject: "求财", text: "阻"), .init(subject: "交易", text: "难"), .init(subject: "婚姻", text: "待时"), .init(subject: "六甲", text: "祈保"), .init(subject: "行人", text: "迟"), .init(subject: "田蚕", text: "滞"), .init(subject: "六畜", text: "滞"), .init(subject: "寻人", text: "见"), .init(subject: "公讼", text: "亏"), .init(subject: "移徙", text: "吉"), .init(subject: "失物", text: "空"), .init(subject: "疾病", text: "求神保佑"), .init(subject: "山坟", text: "不安")], theme: "追逐与风险：目标明确时，也不要忽略途中代价。", story: "马超追曹的情节取自三国演义，借追逐与转折表现局势多变，提醒行进中评估风险。"),
        .init(id: 55, title: "周武王登位", rank: "中签", palace: "丑宫", poem: "父贤传子子传孙\n衣食丰隆只靠天\n堂上椿萱人快乐\n饥饭渴饮困时眠", poeticMeaning: "此卦接竹引泉之象。凡事谋望大吉也。", explanation: "接竹引泉。流传不绝。君子谋望。无不欣悦。", omens: [.init(subject: "家宅", text: "欠安"), .init(subject: "自身", text: "还愿"), .init(subject: "求财", text: "利"), .init(subject: "交易", text: "成"), .init(subject: "婚姻", text: "合"), .init(subject: "六甲", text: "平安"), .init(subject: "行人", text: "动"), .init(subject: "田蚕", text: "吉"), .init(subject: "六畜", text: "损"), .init(subject: "寻人", text: "难"), .init(subject: "公讼", text: "有贵人"), .init(subject: "移徙", text: "吉"), .init(subject: "失物", text: "见"), .init(subject: "疾病", text: "禳星"), .init(subject: "山坟", text: "安")], theme: "转换与秩序：新的阶段，需要明确目标和可以执行的规则。", story: "周武王伐纣、建立周朝的叙事构成登位题材，传统签题借此表现旧局结束与新局展开。"),
        .init(id: 56, title: "禄山谋反", rank: "中签", palace: "丑宫", poem: "滩小石溪流水响\n清风明月贵人忙\n路须借问何方去\n莫取林中花草香", poeticMeaning: "此卦船行小滩之象。凡事有贵人助也。", explanation: "营谋用事。劳心费力。守旧待时。凡事大吉。", omens: [.init(subject: "家宅", text: "安"), .init(subject: "自身", text: "吉"), .init(subject: "求财", text: "中平"), .init(subject: "交易", text: "利"), .init(subject: "婚姻", text: "遂意"), .init(subject: "六甲", text: "男"), .init(subject: "行人", text: "至"), .init(subject: "田蚕", text: "秋利"), .init(subject: "六畜", text: "损"), .init(subject: "寻人", text: "至"), .init(subject: "公讼", text: "有理"), .init(subject: "移徙", text: "吉"), .init(subject: "失物", text: "滞"), .init(subject: "疾病", text: "即安"), .init(subject: "山坟", text: "宜修")], theme: "纷争与审慎：复杂处境中，先核实信息并减少冲动承诺。", story: "安禄山起兵的历史在民间讲述中常被用来表现动荡。阅读签题不等于预示现实会发生灾变。"),
        .init(id: 57, title: "董仲寻亲", rank: "中签", palace: "丑宫", poem: "说是说非风过耳\n好衣好禄自然丰\n君莫记取当年事\n汝意还如我意同", poeticMeaning: "此卦孩儿见母之象。诸事贵人大吉也。", explanation: "所用谋望。皆大欢喜。从公用力。如子逢娘。", omens: [.init(subject: "家宅", text: "不安"), .init(subject: "自身", text: "平平"), .init(subject: "求财", text: "顺"), .init(subject: "交易", text: "成"), .init(subject: "婚姻", text: "合"), .init(subject: "六甲", text: "女"), .init(subject: "行人", text: "阻"), .init(subject: "田蚕", text: "就"), .init(subject: "六畜", text: "损"), .init(subject: "寻人", text: "难"), .init(subject: "公讼", text: "宜和"), .init(subject: "移徙", text: "守旧"), .init(subject: "失物", text: "空"), .init(subject: "疾病", text: "祈福"), .init(subject: "山坟", text: "吉")], theme: "寻找与耐心：重要关系中的疑问，适合通过真实沟通核实。", story: "董仲寻亲源于董永故事体系的后续传说，写寻访亲缘和身份的过程，各地讲述不同。"),
        .init(id: 58, title: "文王问卜", rank: "中签", palace: "丑宫", poem: "直言说话君须记\n莫在他乡求别艺\n切须守己旧生涯\n除此其余都不利", poeticMeaning: "此卦守旧待时之象。凡事守旧则吉也。", explanation: "得住且住。可取且踞。莫宜别事。只宜守旧。", omens: [.init(subject: "家宅", text: "平常"), .init(subject: "自身", text: "不利"), .init(subject: "求财", text: "吉"), .init(subject: "交易", text: "成"), .init(subject: "婚姻", text: "阻"), .init(subject: "六甲", text: "惊"), .init(subject: "行人", text: "迟"), .init(subject: "田蚕", text: "五分"), .init(subject: "六畜", text: "损"), .init(subject: "寻人", text: "见"), .init(subject: "公讼", text: "亏"), .init(subject: "移徙", text: "守旧"), .init(subject: "失物", text: "凶"), .init(subject: "疾病", text: "欠安"), .init(subject: "山坟", text: "宜改")], theme: "自省与判断：向外求问之后，也要回到事实和自己的选择。", story: "文王问卜的故事在民间签本中常见，借商议、观察与等待表现处事，不能据此验证占卜效力。"),
        .init(id: 59, title: "张良隐山", rank: "中签", palace: "寅宫", poem: "直上重楼去藏身\n四围荆棘绕为林\n天高君命长和短\n得一反成失二人", poeticMeaning: "此卦守旧随时之象。凡事待时则吉。", explanation: "如醉饮酒。只宜守旧。直待时来。无灾无咎。", omens: [.init(subject: "家宅", text: "祈福"), .init(subject: "自身", text: "安"), .init(subject: "求财", text: "平常"), .init(subject: "交易", text: "成"), .init(subject: "婚姻", text: "不合"), .init(subject: "六甲", text: "作福"), .init(subject: "行人", text: "至"), .init(subject: "田蚕", text: "半吉"), .init(subject: "六畜", text: "大利"), .init(subject: "寻人", text: "阻"), .init(subject: "公讼", text: "亏"), .init(subject: "移徙", text: "吉"), .init(subject: "失物", text: "凶"), .init(subject: "疾病", text: "祈福"), .init(subject: "山坟", text: "吉")], theme: "归隐与取舍：功业之外，生活需要什么也值得认真回答。", story: "张良在辅佐刘邦后逐渐淡出政事，民间故事常以隐山表现功成知退与重新选择生活。"),
        .init(id: 60, title: "赤壁鏖兵", rank: "下签", palace: "寅宫", poem: "抱薪救火大皆燃\n烧遍三千亦复然\n若问荣华并出入\n不如收拾枉劳心", poeticMeaning: "此卦抱薪救火之象。凡事亦自谨防也。", explanation: "有千般计。不如莫动。一旦相惹。恐祸归身。", omens: [.init(subject: "家宅", text: "凶"), .init(subject: "自身", text: "祈保"), .init(subject: "求财", text: "微微"), .init(subject: "交易", text: "不合"), .init(subject: "婚姻", text: "不合"), .init(subject: "六甲", text: "险"), .init(subject: "行人", text: "滞"), .init(subject: "田蚕", text: "不利"), .init(subject: "六畜", text: "损"), .init(subject: "寻人", text: "杳"), .init(subject: "公讼", text: "亏"), .init(subject: "移徙", text: "吉"), .init(subject: "失物", text: "西方"), .init(subject: "疾病", text: "有惊"), .init(subject: "山坟", text: "平平")], theme: "协作与条件：策略能否奏效，要看资源、环境和团队。", story: "赤壁鏖兵取自三国题材，写联盟与战局变化。文学叙事对风火等情节有艺术加工。"),
        .init(id: 61, title: "苏小妹难夫", rank: "中签", palace: "寅宫", poem: "日上吟诗月下歌\n逢场作戏笑呵呵\n相逢会遇难藏避\n唱彩齐唱连理罗", poeticMeaning: "此卦守旧随时之象。凡事时吉利也。", explanation: "佳人在屋。吟唱诗曲。一片欢心。命中祸福。", omens: [.init(subject: "家宅", text: "安"), .init(subject: "自身", text: "吉"), .init(subject: "求财", text: "顺"), .init(subject: "交易", text: "利"), .init(subject: "婚姻", text: "成"), .init(subject: "六甲", text: "女"), .init(subject: "行人", text: "至"), .init(subject: "田蚕", text: "熟"), .init(subject: "六畜", text: "旺"), .init(subject: "寻人", text: "至"), .init(subject: "移徙", text: "吉"), .init(subject: "失物", text: "凶"), .init(subject: "公讼", text: "有理"), .init(subject: "疾病", text: "即痊愈"), .init(subject: "山坟", text: "大吉")], theme: "才思与尊重：交流中的机敏，也要给彼此留余地。", story: "苏小妹难夫是围绕苏氏兄妹和秦少游形成的民间才子故事，并非可直接当作史实的记载。"),
        .init(id: 62, title: "唐僧得道", rank: "中签", palace: "寅宫", poem: "晨昏全赖佛扶持\n须是逢危却不危\n若得贵人相引处\n那时财帛亦相随", poeticMeaning: "此卦神佛暗佑之象。凡事忍耐大吉也。", explanation: "平平稳稳。四方名显。改旧从新。亦无凶险。", omens: [.init(subject: "家宅", text: "安"), .init(subject: "自身", text: "吉"), .init(subject: "求财", text: "西方"), .init(subject: "交易", text: "遂"), .init(subject: "婚姻", text: "成"), .init(subject: "六甲", text: "祈福"), .init(subject: "行人", text: "阻"), .init(subject: "田蚕", text: "七分"), .init(subject: "六畜", text: "利"), .init(subject: "寻人", text: "西方"), .init(subject: "公讼", text: "亏"), .init(subject: "移徙", text: "守旧"), .init(subject: "失物", text: "见"), .init(subject: "疾病", text: "祈福"), .init(subject: "山坟", text: "吉")], theme: "坚持与归来：经历之后，整理哪些方法真正帮助了你。", story: "唐僧得道借取经完成的叙事表现长期历练、伙伴协作和阶段收束。"),
        .init(id: 63, title: "女娲氏炼石", rank: "中签", palace: "卯宫", poem: "昔然行船失了针\n今朝依旧海中寻\n若然寻得原针在\n也费工夫也费心", poeticMeaning: "此卦海中寻针之象。凡事费心劳力也。", explanation: "福是禄基。禄是福种。说得分明。切宜守谨。", omens: [.init(subject: "家宅", text: "欠利"), .init(subject: "自身", text: "谨防"), .init(subject: "求财", text: "有"), .init(subject: "交易", text: "成"), .init(subject: "婚姻", text: "不合"), .init(subject: "六甲", text: "阻"), .init(subject: "行人", text: "滞"), .init(subject: "田蚕", text: "吉"), .init(subject: "六畜", text: "莫养"), .init(subject: "寻人", text: "难"), .init(subject: "公讼", text: "宜和"), .init(subject: "移徙", text: "宜迁"), .init(subject: "失物", text: "凶"), .init(subject: "疾病", text: "难痊"), .init(subject: "山坟", text: "暂安")], theme: "修补与合作：面对缺口，先看看能够补足的部分和可用帮助。", story: "女娲炼石补天是中国神话，借修补破损与重建秩序表达照护，不是对自然现象的解释。"),
        .init(id: 64, title: "马前覆水", rank: "下签", palace: "卯宫", poem: "游鱼却在碧波池\n撞遭罗网四边围\n思量无计翻身出\n事到头来惹事非", poeticMeaning: "此卦鱼遭罗网之象。凡事亦宜提防也。", explanation: "屋下安身。祸从天降。早觉先防。免遭灾殃。", omens: [.init(subject: "家宅", text: "凶"), .init(subject: "自身", text: "险"), .init(subject: "求财", text: "虚"), .init(subject: "交易", text: "中平"), .init(subject: "婚姻", text: "不合"), .init(subject: "六甲", text: "惊"), .init(subject: "行人", text: "有阻"), .init(subject: "田蚕", text: "损"), .init(subject: "六畜", text: "衰"), .init(subject: "寻人", text: "杳"), .init(subject: "公讼", text: "亏"), .init(subject: "移徙", text: "吉"), .init(subject: "失物", text: "凶"), .init(subject: "疾病", text: "有灾险"), .init(subject: "山坟", text: "宜改")], theme: "失去与边界：有些事能修复，有些关系也需要尊重结束。", story: "马前覆水的故事常与朱买臣、姜子牙等人物相连，借覆水难收表达选择与后果，版本不同。"),
        .init(id: 65, title: "孙膑困庞涓", rank: "下签", palace: "卯宫", poem: "眼前欢喜未为欢\n亦不危时亦不安\n割肉补疮为甚事\n不如守旧待时光", poeticMeaning: "此卦割肉成疮之象。凡事只宜守旧待时。", explanation: "知止则止。知宽自宽。割自身肉。疾痛一般。", omens: [.init(subject: "家宅", text: "不安"), .init(subject: "自身", text: "口舌"), .init(subject: "求财", text: "不利"), .init(subject: "交易", text: "小人"), .init(subject: "婚姻", text: "不长"), .init(subject: "六甲", text: "有惊"), .init(subject: "行人", text: "阻"), .init(subject: "田蚕", text: "损"), .init(subject: "六畜", text: "损"), .init(subject: "寻人", text: "招非"), .init(subject: "公讼", text: "亏"), .init(subject: "移徙", text: "守旧"), .init(subject: "失物", text: "难寻"), .init(subject: "疾病", text: "反复")], theme: "智慧与预防：竞争之中，仍要明确底线与可承受的代价。", story: "孙膑与庞涓的斗智故事在战国题材中广为流传，借谋划与反转表现判断和准备。"),
        .init(id: 66, title: "霸王被困", rank: "下签", palace: "卯宫", poem: "路险马乏人行急\n失群军卒困相当\n滩高风浪船棹破\n日暮花残天降霜", poeticMeaning: "此卦船破下滩之象。凡事险阻提防也。", explanation: "守旧待时。安静无咎。不用求谋。自在悠游。", omens: [.init(subject: "家宅", text: "忧疑"), .init(subject: "自身", text: "灾耗"), .init(subject: "求财", text: "破失"), .init(subject: "交易", text: "败"), .init(subject: "婚姻", text: "不长"), .init(subject: "六甲", text: "危险"), .init(subject: "行人", text: "阻"), .init(subject: "田蚕", text: "损"), .init(subject: "六畜", text: "损"), .init(subject: "寻人", text: "杳"), .init(subject: "公讼", text: "亏"), .init(subject: "移徙", text: "莫动"), .init(subject: "山坟", text: "不利"), .init(subject: "疾病", text: "即设送")], theme: "困局与求助：压力很大时，先寻找支撑，而非独自承受一切。", story: "霸王被困常取意项羽末路的故事。签题是文学参照，不意味着个人困境会有相同结局。"),
        .init(id: 67, title: "金精试窦儿", rank: "上签", palace: "卯宫", poem: "一条金线秤君心\n无减无增无重轻\n为人平生心正直\n文章全具艺光明", poeticMeaning: "此卦心平正直之象。凡事安稳无凶也。", explanation: "心平正直。到底清平。只依本份。天下太平。", omens: [.init(subject: "家宅", text: "安"), .init(subject: "自身", text: "平"), .init(subject: "求财", text: "守慎"), .init(subject: "交易", text: "稳"), .init(subject: "婚姻", text: "合"), .init(subject: "六甲", text: "男"), .init(subject: "行人", text: "有信"), .init(subject: "田蚕", text: "稳"), .init(subject: "六畜", text: "安"), .init(subject: "寻人", text: "迟"), .init(subject: "公讼", text: "和"), .init(subject: "移徙", text: "守旧"), .init(subject: "失物", text: "见"), .init(subject: "山坟", text: "平"), .init(subject: "疾病", text: "禳星")], theme: "诚信与自省：在无人注视时，也可以按自己的原则行动。", story: "金精试窦儿属于劝善传说，以考验人物言行表达诚实与自守。"),
        .init(id: 68, title: "汾阳祝寿", rank: "中签", palace: "卯宫", poem: "门廷吉庆喜非常\n积善之门大吉昌\n婚姻田蚕诸事遂\n病逢妙药即安康", poeticMeaning: "此卦门廷吉庆之象。凡事顺遂也。", explanation: "积善之家。必有余庆。忠义之门。拱照福星。", omens: [.init(subject: "家宅", text: "旺"), .init(subject: "自身", text: "安"), .init(subject: "求财", text: "春旺"), .init(subject: "交易", text: "遂"), .init(subject: "婚姻", text: "成"), .init(subject: "六甲", text: "防惊"), .init(subject: "行人", text: "到"), .init(subject: "田蚕", text: "利"), .init(subject: "六畜", text: "旺"), .init(subject: "寻人", text: "至"), .init(subject: "公讼", text: "胜"), .init(subject: "移徙", text: "如意"), .init(subject: "失物", text: "急寻"), .init(subject: "疾病", text: "安"), .init(subject: "山坟", text: "大吉")], theme: "积善与相处：日常如何对待身边的人，比追求仪式回报更具体。", story: "郭子仪汾阳祝寿的故事常见于戏曲与年画，借阖家聚会表达长辈、亲情与团圆。"),
        .init(id: 69, title: "梅开二度", rank: "中签", palace: "辰宫", poem: "冬来岭上一枝梅\n叶落枝枯终不摧\n但得阳春悄急至\n依然还我作花魁", poeticMeaning: "此卦梅花占魁之象。凡事宜迟则吉也。", explanation: "一箭射空。当空不空。待等春来。彩在其中。", omens: [.init(subject: "家宅", text: "欠利"), .init(subject: "自身", text: "作福"), .init(subject: "求财", text: "谨慎"), .init(subject: "交易", text: "待时"), .init(subject: "婚姻", text: "迟成"), .init(subject: "六甲", text: "春实秋虚"), .init(subject: "行人", text: "迟至"), .init(subject: "田蚕", text: "旺"), .init(subject: "六畜", text: "旺"), .init(subject: "寻人", text: "见"), .init(subject: "公讼", text: "亏"), .init(subject: "失物", text: "东方"), .init(subject: "疾病", text: "虚惊"), .init(subject: "山坟", text: "宜改")], theme: "再开与成长：第二次机会也需要新方法和新的现实条件。", story: "梅开二度是传统戏曲故事，借梅花重开与人物际遇变化表现逆境中的重新开始。"),
        .init(id: 70, title: "李密反唐", rank: "下签", palace: "辰宫", poem: "朝朝恰似采花蜂\n飞出西南又走东\n春尽花残无觅处\n此心不变旧行踪", poeticMeaning: "此卦蜜蜂采花之象。凡事劳心费力也。", explanation: "无觅春色。久雨不晴。求谋用事。不如安静。", omens: [.init(subject: "家宅", text: "口舌"), .init(subject: "自身", text: "小人"), .init(subject: "求财", text: "破耗"), .init(subject: "交易", text: "反复"), .init(subject: "婚姻", text: "不长"), .init(subject: "六甲", text: "虚花"), .init(subject: "行人", text: "杳"), .init(subject: "田蚕", text: "损"), .init(subject: "六畜", text: "损"), .init(subject: "寻人", text: "无踪"), .init(subject: "公讼", text: "亏"), .init(subject: "移徙", text: "守旧"), .init(subject: "失物", text: "空"), .init(subject: "疾病", text: "有阻"), .init(subject: "山坟", text: "改")], theme: "志向与分歧：选择道路之前，确认自己的理由和实际代价。", story: "李密反唐属于隋唐演义题材，具体叙事与史实不完全一致。签题借立场变化表现选择。"),
        .init(id: 71, title: "文君访相如", rank: "中签", palace: "辰宫", poem: "认知苍龙下九衢\n女子当年嫁二夫\n自是一弓架两箭\n欲恐龙马不安居", poeticMeaning: "此卦一弓架两箭之象。凡事再合则吉也。", explanation: "不出重重。事由天命。振放中开。切宜谨守。", omens: [.init(subject: "家宅", text: "损失"), .init(subject: "自身", text: "是非"), .init(subject: "求财", text: "劳力"), .init(subject: "交易", text: "谨防"), .init(subject: "婚姻", text: "再合"), .init(subject: "六甲", text: "先虚后实"), .init(subject: "行人", text: "阻"), .init(subject: "田蚕", text: "晚收"), .init(subject: "六畜", text: "损"), .init(subject: "寻人", text: "见"), .init(subject: "公讼", text: "亏"), .init(subject: "移徙", text: "吉"), .init(subject: "疾病", text: "禳星"), .init(subject: "山坟", text: "改")], theme: "表达与自主：关系中的靠近，应该建立在彼此自愿之上。", story: "卓文君与司马相如的故事流传于史传和文学，常以音乐、相知与自主选择寄意。"),
        .init(id: 72, title: "王莽求贤", rank: "中签", palace: "辰宫", poem: "养蜂须用求他蜜\n只怕遭触尾上针\n须是眼前有异路\n暗里深如荆棘林", poeticMeaning: "此卦结蜂采蜜之象,诸事劳心费力。此卦求甜得苦之象凡事防范灾殃", explanation: "事须仔细。不用强求。结蜂采蜜。有甚来由。", omens: [.init(subject: "家宅", text: "欠利"), .init(subject: "自身", text: "防"), .init(subject: "求财", text: "阻"), .init(subject: "交易", text: "迟"), .init(subject: "婚姻", text: "阻隔"), .init(subject: "六甲", text: "虚惊"), .init(subject: "行人", text: "迟"), .init(subject: "田蚕", text: "少收"), .init(subject: "六畜", text: "少收"), .init(subject: "寻人", text: "难"), .init(subject: "公讼", text: "亏"), .init(subject: "移徙", text: "莫动"), .init(subject: "失物", text: "凶"), .init(subject: "疾病", text: "设送"), .init(subject: "山坟", text: "败")], theme: "名实与核查：好听的承诺，也需要看真实行动。", story: "王莽求贤的签题借古代政治故事表现名声与实际的关系，不必将历史人物直接套入当下。"),
        .init(id: 73, title: "陈桥兵变", rank: "上签", palace: "巳宫", poem: "春来雷震百虫鸣\n番身一转离泥中\n始知出入还来往\n一朝变化便成龙", poeticMeaning: "此卦雷发百虫之象。凡事遇贵人吉兆也。", explanation: "雷发时转。出入两存。一朝变化。直到天门。", omens: [.init(subject: "家宅", text: "祈福"), .init(subject: "自身", text: "平常"), .init(subject: "求财", text: "春利"), .init(subject: "交易", text: "贵人"), .init(subject: "婚姻", text: "成合"), .init(subject: "六甲", text: "男"), .init(subject: "行人", text: "到"), .init(subject: "田蚕", text: "早生"), .init(subject: "六畜", text: "春利"), .init(subject: "寻人", text: "见"), .init(subject: "公讼", text: "胜"), .init(subject: "移徙", text: "吉"), .init(subject: "疾病", text: "险阻"), .init(subject: "山坟", text: "吉")], theme: "变化与承担：新的位置并不减少责任，反而需要更清楚的准备。", story: "陈桥兵变写赵匡胤黄袍加身、建立宋朝的历史转折，民间讲述常以身份骤变寄意。"),
        .init(id: 74, title: "秦败擒三帅", rank: "下签", palace: "巳宫", poem: "似鹄飞来自入笼\n欲得番身却不通\n南北东西都难出\n此卦诚恐恨无穹", poeticMeaning: "此卦似鹄投笼之象。凡事多虚少实也。", explanation: "进身不得。退步为难。低头直去。悉在其中。", omens: [.init(subject: "家宅", text: "不安"), .init(subject: "自身", text: "困滞"), .init(subject: "求财", text: "小人"), .init(subject: "交易", text: "破耗"), .init(subject: "婚姻", text: "刑伤"), .init(subject: "六甲", text: "刑劫"), .init(subject: "行人", text: "阻"), .init(subject: "田蚕", text: "缺"), .init(subject: "六畜", text: "瘟"), .init(subject: "寻人", text: "杳"), .init(subject: "公讼", text: "祸"), .init(subject: "移徙", text: "不利"), .init(subject: "失物", text: "凶"), .init(subject: "疾病", text: "延"), .init(subject: "山坟", text: "绝")], theme: "受挫与复盘：遇到损失时，先停止扩大投入，再整理原因。", story: "秦败擒三帅常与崤之战的故事相连，借轻进与失利提醒准备和对局势的判断。"),
        .init(id: 75, title: "伍员夜出昭关", rank: "中签", palace: "午宫", poem: "恰如抱虎过高山\n战战竞竞胆碎寒\n不觉忽然从好事\n切须保守一身安", poeticMeaning: "此卦抱虎过山之象。凡事险凶惊恐也。", explanation: "危危险险。前程有阻。若问求谋。到底辛苦。", omens: [.init(subject: "家宅", text: "祈保"), .init(subject: "自身", text: "提防"), .init(subject: "求财", text: "谨慎"), .init(subject: "交易", text: "滞"), .init(subject: "婚姻", text: "难顺"), .init(subject: "六甲", text: "有惊"), .init(subject: "行人", text: "阻"), .init(subject: "田蚕", text: "五分"), .init(subject: "六畜", text: "损"), .init(subject: "寻人", text: "杳"), .init(subject: "公讼", text: "亏"), .init(subject: "移徙", text: "守"), .init(subject: "失物", text: "难"), .init(subject: "疾病", text: "祭虎"), .init(subject: "山坟", text: "凶")], theme: "难关与援助：压力之下，可靠的信息与支持尤其重要。", story: "伍子胥出昭关的故事在戏曲中常见，写逃难过程中的阻碍与帮助，各版本情节不一。"),
        .init(id: 76, title: "洪武看牛", rank: "中签", palace: "午宫", poem: "鱼龙混杂意相同\n耐守深潭待运通\n不觉一朝头耸出\n禹门一跳过龙宫", poeticMeaning: "此卦鱼龙未变之象。凡事待时至可也。", explanation: "虽是滋基。也要待时。营谋自本。切莫妄为。", omens: [.init(subject: "家宅", text: "平安"), .init(subject: "自身", text: "康泰"), .init(subject: "求财", text: "有"), .init(subject: "交易", text: "待时"), .init(subject: "婚姻", text: "迟合"), .init(subject: "六甲", text: "生男"), .init(subject: "行人", text: "迟"), .init(subject: "田蚕", text: "晚丰"), .init(subject: "六畜", text: "尾利"), .init(subject: "寻人", text: "未遇"), .init(subject: "公讼", text: "延"), .init(subject: "移徙", text: "守旧"), .init(subject: "疾病", text: "阻"), .init(subject: "山坟", text: "发")], theme: "起点与未来：出身或当下处境，不足以决定一个人的全部。", story: "洪武看牛取自朱元璋少年经历的民间讲述，借普通起点与后来变化表现人生道路复杂。"),
        .init(id: 77, title: "捧璧归赵", rank: "中签", palace: "午宫", poem: "梦中说得是多财\n声名云外总虚来\n水远山遥难信实\n贵人指点笑颜开", poeticMeaning: "此卦梦中得宝之象。凡事虚多少实也。", explanation: "如梦说梦。声名莫望。只待好时。贵人指示。", omens: [.init(subject: "家宅", text: "祈福"), .init(subject: "自身", text: "阻"), .init(subject: "求财", text: "虚"), .init(subject: "交易", text: "难成"), .init(subject: "婚姻", text: "不合"), .init(subject: "六甲", text: "虚"), .init(subject: "行人", text: "迟"), .init(subject: "田蚕", text: "不收"), .init(subject: "六畜", text: "损"), .init(subject: "寻人", text: "杳"), .init(subject: "公讼", text: "和"), .init(subject: "移徙", text: "待时"), .init(subject: "失物", text: "远"), .init(subject: "疾病", text: "设送"), .init(subject: "山坟", text: "改")], theme: "守信与协商：维护重要事物时，既要坚持原则，也要选择方法。", story: "蔺相如完璧归赵的故事见于史传，写交涉中守护和氏璧、维护国家权益。"),
        .init(id: 78, title: "临潼救驾", rank: "上签", palace: "午宫", poem: "冷水未烧白涕汤\n不寒不热有温凉\n要行天下无他事\n为有身中百艺强", poeticMeaning: "此卦平善用事之象。凡事平稳大吉也。", explanation: "囚人逢赦。病遇良医。求财谋望。贵人指示。", omens: [.init(subject: "家宅", text: "安"), .init(subject: "自身", text: "吉"), .init(subject: "求财", text: "遂"), .init(subject: "交易", text: "成"), .init(subject: "婚姻", text: "合"), .init(subject: "六甲", text: "男"), .init(subject: "行人", text: "至"), .init(subject: "田蚕", text: "熟"), .init(subject: "六畜", text: "旺"), .init(subject: "寻人", text: "至"), .init(subject: "公讼", text: "散"), .init(subject: "移徙", text: "大吉"), .init(subject: "失物", text: "即见"), .init(subject: "疾病", text: "安然"), .init(subject: "山坟", text: "大吉利")], theme: "临危与担当：帮忙之前，也评估自己的能力和安全边界。", story: "临潼救驾属于说唐故事，常写秦琼等人物护驾。签本中的人物配置有差异。"),
        .init(id: 79, title: "暗扶倒铜旗", rank: "中签", palace: "午宫", poem: "虚空结愿保平安\n保得身安愿不还\n莫忘神圣宜还了\n此知神语莫轻慢", poeticMeaning: "此卦信实莫信虚之象。凡事守旧之兆也。", explanation: "人有我见。心不用忙。观音指示。切莫轻慢。", omens: [.init(subject: "家宅", text: "还愿"), .init(subject: "自身", text: "许经"), .init(subject: "求财", text: "守份"), .init(subject: "交易", text: "谨慎"), .init(subject: "婚姻", text: "虚"), .init(subject: "六甲", text: "生女"), .init(subject: "行人", text: "滞"), .init(subject: "田蚕", text: "七分"), .init(subject: "六畜", text: "损"), .init(subject: "寻人", text: "杳"), .init(subject: "公讼", text: "和"), .init(subject: "移徙", text: "守"), .init(subject: "失物", text: "西方"), .init(subject: "疾病", text: "解"), .init(subject: "山坟", text: "西向")], theme: "暗处与支持：未被看见的帮助，也可能来自具体的合作。", story: "倒铜旗是民间戏曲、演义中的战阵题材，借隐蔽援助与局面反转表达协力。"),
        .init(id: 80, title: "智远投军", rank: "上签", palace: "未宫", poem: "直上仙岩要学仙\n此知一旦帝王宣\n青天日月常明照\n心正声名四海传", poeticMeaning: "此卦贵人接引之象。凡事和合大吉也。", explanation: "有始有终。莫向西东。心中用事。贵人重重。", omens: [.init(subject: "家宅", text: "平安"), .init(subject: "自身", text: "吉利"), .init(subject: "求财", text: "有利"), .init(subject: "交易", text: "遂意"), .init(subject: "婚姻", text: "双配"), .init(subject: "六甲", text: "男"), .init(subject: "行人", text: "回"), .init(subject: "田蚕", text: "半收"), .init(subject: "六畜", text: "胜"), .init(subject: "寻人", text: "遇"), .init(subject: "公讼", text: "胜"), .init(subject: "移徙", text: "吉"), .init(subject: "失物", text: "南"), .init(subject: "疾病", text: "安"), .init(subject: "山坟", text: "吉")], theme: "转向与行动：面对新道路，先了解真实要求，再逐步尝试。", story: "刘智远投军的故事见于五代题材和民间戏曲，常与李三娘的离合情节相连。"),
        .init(id: 81, title: "风送滕王阁", rank: "上签", palace: "未宫", poem: "梧桐叶落秋将暮\n行客归程去似云\n谢得天公高着力\n顺风船载宝珍归", poeticMeaning: "此卦梧桐叶落之象。凡事先凶后吉也。", explanation: "心中取事。天必从之。营谋用事。尽可施为。", omens: [.init(subject: "家宅", text: "祈保"), .init(subject: "自身", text: "许经"), .init(subject: "求财", text: "遂意"), .init(subject: "交易", text: "成"), .init(subject: "婚姻", text: "和合"), .init(subject: "六甲", text: "虚惊"), .init(subject: "行人", text: "动"), .init(subject: "田蚕", text: "晚胜"), .init(subject: "六畜", text: "稳"), .init(subject: "寻人", text: "至"), .init(subject: "公讼", text: "胜"), .init(subject: "移徙", text: "随意"), .init(subject: "疾病", text: "喜"), .init(subject: "山坟", text: "择地")], theme: "才华与机缘：展示准备好的能力，也接受条件带来的变化。", story: "王勃赴滕王阁宴的传说常说遇风助行。故事以文章、机会和相遇寄意，文学加工明显。"),
        .init(id: 82, title: "火烧葫芦谷", rank: "中签", palace: "未宫", poem: "炎炎烈火焰连天\n焰里还生一朵莲\n到底得成终不害\n依然生叶长根枝", poeticMeaning: "此卦火里生莲之象。凡事似险非险也。", explanation: "虽然逢险。不损其身。营谋用事。皆遇贵人。", omens: [.init(subject: "家宅", text: "欠安"), .init(subject: "自身", text: "谨防"), .init(subject: "求财", text: "劳力"), .init(subject: "交易", text: "小人"), .init(subject: "婚姻", text: "阻"), .init(subject: "六甲", text: "虚惊"), .init(subject: "行人", text: "阻"), .init(subject: "田蚕", text: "缺"), .init(subject: "六畜", text: "损"), .init(subject: "寻人", text: "西"), .init(subject: "公讼", text: "亏"), .init(subject: "移徙", text: "守旧"), .init(subject: "失物", text: "南"), .init(subject: "疾病", text: "设送"), .init(subject: "山坟", text: "改")], theme: "变局与预案：计划之外的变化，需要预留应对空间。", story: "火烧葫芦谷取自三国演义，写谋划受天气变化影响，借此提醒条件并不完全可控。"),
        .init(id: 83, title: "李渊登位", rank: "中签", palace: "未宫", poem: "譬若初三四五缺\n半无半有未圆全\n等待十五良宵夜\n到处光明到处圆", poeticMeaning: "此卦月缺未圆之象，凡事候时则吉也。", explanation: "守旧待时 如月初出 待等圆时 无有不吉", omens: [.init(subject: "家宅", text: "许愿"), .init(subject: "自身", text: "夏秋吉"), .init(subject: "求财", text: "谨守"), .init(subject: "交易", text: "待时"), .init(subject: "婚姻", text: "迟"), .init(subject: "六甲", text: "生女"), .init(subject: "行人", text: "阻"), .init(subject: "田蚕", text: "平稳"), .init(subject: "六畜", text: "平稳"), .init(subject: "寻人", text: "难"), .init(subject: "公讼", text: "和"), .init(subject: "移徙", text: "守旧"), .init(subject: "失物", text: "难"), .init(subject: "疾病", text: "设送"), .init(subject: "山坟", text: "改")], theme: "开局与资源：承担更大的目标时，也要看清基础与责任。", story: "李渊登位的题材取自唐朝建立的历史，签本常借新的开端和局势变化寄意。"),
        .init(id: 84, title: "庄子试妻", rank: "下签", palace: "未宫", poem: "因名丧德如何事\n切恐吉中变化凶\n酒醉不知何处去\n青松影里梦朦胧", poeticMeaning: "寒鱼离水招凶之象。凡事不可移动也。", explanation: "寒鱼离水。美中不足。若问营谋。不如莫起。", omens: [.init(subject: "总述", text: "此签六甲煞旺；诸事不利；禳灾保安")], theme: "猜疑与信任：不要用试探代替真诚沟通，也尊重对方边界。", story: "庄子试妻是后世民间故事，并非《庄子》原典。本版不把带偏见的试探情节当作相处建议。"),
        .init(id: 85, title: "韩文公遇雪", rank: "中签", palace: "申宫", poem: "云开雾罩山前路\n万物圆中月再圆\n若得诗书沉梦醒\n贵人指引步天台", poeticMeaning: "此卦春尽花开之象。凡事主后改变也。", explanation: "老者用求。春残再开。欲求名利。晚遇横财。", omens: [.init(subject: "家宅", text: "欠利"), .init(subject: "自身", text: "谨慎"), .init(subject: "求财", text: "着力"), .init(subject: "交易", text: "平"), .init(subject: "婚姻", text: "迟"), .init(subject: "六甲", text: "女"), .init(subject: "行人", text: "阻"), .init(subject: "田蚕", text: "好"), .init(subject: "六畜", text: "好"), .init(subject: "寻人", text: "难"), .init(subject: "公讼", text: "反复"), .init(subject: "移徙", text: "更新"), .init(subject: "失物", text: "凶"), .init(subject: "疾病", text: "延滞"), .init(subject: "山坟", text: "宜改")], theme: "受阻与照顾：环境不利时，先安排好身体和眼前的需要。", story: "韩愈遇雪常与贬谪蓝关、侄孙来相助的文学意象相连，借旅途艰难与亲人相见寄意。"),
        .init(id: 86, title: "商辂中三元", rank: "上签", palace: "申宫", poem: "春来花发映阳台\n万里车来进宝财\n若得禹门三级浪\n恰如平地一声雷", poeticMeaning: "此卦上朝见帝之象。凡事太吉大利也。", explanation: "朝帝受职。如贫得宝。谋望从心。卦中第一。", omens: [.init(subject: "总述", text: "此签从心所欲；诸事皆吉")], theme: "勤学与检验：积累之后，仍需要通过真实反馈认识自己。", story: "商辂中三元的签题借科举成名故事表现学习与机会，民间叙述中亦有夸饰。"),
        .init(id: 87, title: "咬金探地穴", rank: "中签", palace: "申宫", poem: "人行半岭日衔山\n竣岭崖岩未可安\n仰望上天为护佑\n此身犹在太平间", poeticMeaning: "此卦淘沙见金人处险境之象。凡事有贵人之兆也。", explanation: "凿石见玉。淘沙见金。须要着力。只是劳心。", omens: [.init(subject: "家宅", text: "祈福"), .init(subject: "自身", text: "欠利"), .init(subject: "求财", text: "劳心"), .init(subject: "交易", text: "谨慎"), .init(subject: "婚姻", text: "有阻"), .init(subject: "六甲", text: "虚"), .init(subject: "行人", text: "迟"), .init(subject: "田蚕", text: "平稳"), .init(subject: "六畜", text: "平稳"), .init(subject: "寻人", text: "未遇"), .init(subject: "公讼", text: "亏"), .init(subject: "移徙", text: "守"), .init(subject: "失物", text: "凶"), .init(subject: "疾病", text: "阻"), .init(subject: "山坟", text: "不阻")], theme: "探索与边界：好奇心值得保留，未知也需要谨慎进入。", story: "程咬金探地穴属于说唐民间故事，借偶然发现与未知空间表达探索，不鼓励冒险模仿。"),
        .init(id: 88, title: "庞洪畏包公", rank: "中签", palace: "酉宫", poem: "木为一虎在当门\n须是有威不害人\n分明说是无防事\n忧恼迟疑恐惊心", poeticMeaning: "此卦木虎有威之象。凡事虚惊少实也。", explanation: "炉头点雪。似耳边风。可宜作福。后吉前凶。", omens: [.init(subject: "家宅", text: "不安"), .init(subject: "自身", text: "口舌"), .init(subject: "求财", text: "小人"), .init(subject: "交易", text: "不利"), .init(subject: "婚姻", text: "不合"), .init(subject: "六甲", text: "虚险"), .init(subject: "行人", text: "阻"), .init(subject: "田蚕", text: "损"), .init(subject: "六畜", text: "损"), .init(subject: "寻人", text: "杳"), .init(subject: "公讼", text: "亏"), .init(subject: "移徙", text: "守旧"), .init(subject: "失物", text: "凶"), .init(subject: "疾病", text: "祭虎"), .init(subject: "山坟", text: "凶")], theme: "公正与事实：面对权势或压力，保留证据并寻求正式渠道。", story: "庞洪与包公的故事来自公案戏曲，借权势与公断的对照表达公正，人物叙事并非历史考证。"),
        .init(id: 89, title: "智服姜维", rank: "上签", palace: "酉宫", poem: "出入营谋大吉昌\n似玉无瑕石里藏\n若得贵人来指引\n斯时得宝喜风光", poeticMeaning: "此卦石藏珍宝之象。凡事称心大吉也。", explanation: "如石藏玉。贵人指示。得祗称心。欢怀得意。", omens: [.init(subject: "家宅", text: "吉利"), .init(subject: "自身", text: "康泰"), .init(subject: "求财", text: "遂意"), .init(subject: "交易", text: "成"), .init(subject: "婚姻", text: "成就"), .init(subject: "六甲", text: "生男"), .init(subject: "行人", text: "动"), .init(subject: "田蚕", text: "着力"), .init(subject: "六畜", text: "勤理"), .init(subject: "寻人", text: "见"), .init(subject: "公讼", text: "胜"), .init(subject: "移徙", text: "吉"), .init(subject: "失物", text: "在"), .init(subject: "疾病", text: "安"), .init(subject: "山坟", text: "吉")], theme: "理解与转圜：要促成合作，先了解对方的处境与理由。", story: "智服姜维取自三国演义，写诸葛亮了解并争取姜维的过程，借识才与沟通寄意。"),
        .init(id: 90, title: "苇佩遇仙", rank: "上签", palace: "酉宫", poem: "忽言一信向天飞\n泰山宝贝满船归\n若问路途成好事\n前头仍有贵人推", poeticMeaning: "此卦功名成就之象。凡事宜进大吉也。", explanation: "若问功名。前有贵人。更添喜气。财禄丰盈。", omens: [.init(subject: "总述", text: "此签诸事佳吉。求之顺遂。")], theme: "偶遇与留心：新的启发可以收下，但不必据此作重大承诺。", story: "苇佩遇仙的签题在各地录文中异名较多，属遇仙传说体系。本版不补造具体年代和人物生平。"),
        .init(id: 91, title: "三战吕布", rank: "中签", palace: "酉宫", poem: "好展愁眉出众来\n前途改变喜多财\n一条大路如天阔\n凡有施财尽畅怀", poeticMeaning: "此卦前途显达之象。凡事通泰大吉也。", explanation: "一条大路。可向前行。心中用事。只可向前。", omens: [.init(subject: "总述", text: "此签诸事如心；顺利吉昌")], theme: "竞争与合作：面对强项不同的人，分工可能比独自较劲更有用。", story: "三战吕布常指三英战吕布等三国演义情节，借多方协作与交锋表现局势变化。"),
        .init(id: 92, title: "蔡卿报恩", rank: "上签", palace: "酉宫", poem: "自幼为商任设谋\n财禄盈丰不用求\n若是双身谋望事\n秀才出去状元回", poeticMeaning: "此卦自小为商之象。凡事勤俭无忧也。", explanation: "自小至大。无阻无碍。作意营谋。功名顺遂。", omens: [.init(subject: "家宅", text: "安"), .init(subject: "自身", text: "泰"), .init(subject: "求财", text: "顺遂"), .init(subject: "交易", text: "胜"), .init(subject: "婚姻", text: "合"), .init(subject: "六甲", text: "生男"), .init(subject: "行人", text: "动"), .init(subject: "田蚕", text: "半收"), .init(subject: "六畜", text: "旺"), .init(subject: "寻人", text: "见"), .init(subject: "公讼", text: "胜"), .init(subject: "移徙", text: "如意"), .init(subject: "失物", text: "在"), .init(subject: "疾病", text: "即安"), .init(subject: "山坟", text: "大吉")], theme: "感恩与行动：想表达感谢时，把心意变成对方能接住的小事。", story: "蔡卿报恩属于民间劝善故事，签本叙述各异，核心在记得帮助与合适地回应。"),
        .init(id: 93, title: "高君保招亲", rank: "中签", palace: "戌宫", poem: "鸾凤翔毛雨淋漓\n当时却被雀儿欺\n终教一日云开达\n依旧还君整羽衣", poeticMeaning: "此卦鸾凤被雨之象。凡事待时大利也。", explanation: "小人日盛。君子莫为。只宜守己。待时施为。", omens: [.init(subject: "家宅", text: "欠利"), .init(subject: "自身", text: "谨防"), .init(subject: "求财", text: "阻"), .init(subject: "交易", text: "待时"), .init(subject: "婚姻", text: "迟滞"), .init(subject: "六甲", text: "有虚"), .init(subject: "行人", text: "留连"), .init(subject: "田蚕", text: "晚"), .init(subject: "六畜", text: "损"), .init(subject: "寻人", text: "难"), .init(subject: "公讼", text: "亏"), .init(subject: "移徙", text: "守旧"), .init(subject: "失物", text: "凶"), .init(subject: "疾病", text: "延"), .init(subject: "山坟", text: "改")], theme: "相识与选择：关系的下一步，需要双方的真实意愿。", story: "高君保招亲见于宋代题材的民间演义，常与刘金定相逢相连，借相识与婚约寄意。"),
        .init(id: 94, title: "伯牙访友", rank: "下签", palace: "戌宫", poem: "君子莫体小人为\n事若差池各是非\n琴鸣须用知音听\n守常安静得依稀", poeticMeaning: "此卦要逢知己之象。凡事守常则吉也。", explanation: "知音方许。闲事莫理。待得贵人。无不欢喜。", omens: [.init(subject: "家宅", text: "慎出"), .init(subject: "自身", text: "小人"), .init(subject: "求财", text: "待时"), .init(subject: "交易", text: "谨慎"), .init(subject: "婚姻", text: "宜迟"), .init(subject: "六甲", text: "女"), .init(subject: "行人", text: "动"), .init(subject: "田蚕", text: "少"), .init(subject: "六畜", text: "损"), .init(subject: "寻人", text: "勤"), .init(subject: "公讼", text: "和"), .init(subject: "失物", text: "速寻"), .init(subject: "疾病", text: "阻隔"), .init(subject: "山坟", text: "不利")], theme: "知音与倾听：好的理解来自认真交流，不必急于判断相似程度。", story: "伯牙访友与钟子期知音的故事相连，借高山流水表达理解、倾听和珍惜。"),
        .init(id: 95, title: "曹丕称帝", rank: "中签", palace: "戌宫", poem: "志气功业在朝朝\n今将酒色不胜饶\n若见金鸡报君语\n钱财福禄与君招", poeticMeaning: "此卦志气功名之象。凡事守常大吉也。", explanation: "志气心动。守己未迟。金鸡报诺。无不欢喜。", omens: [.init(subject: "家宅", text: "祈保"), .init(subject: "自身", text: "中平"), .init(subject: "求财", text: "劳心"), .init(subject: "交易", text: "早断"), .init(subject: "婚姻", text: "有成"), .init(subject: "六甲", text: "安"), .init(subject: "田蚕", text: "晚成"), .init(subject: "六畜", text: "成"), .init(subject: "寻人", text: "难"), .init(subject: "公讼", text: "急断"), .init(subject: "移徙", text: "守"), .init(subject: "失物", text: "远"), .init(subject: "疾病", text: "延缠"), .init(subject: "山坟", text: "吉")], theme: "位置与责任：得到一个位置之后，仍要看实际行动是否相称。", story: "曹丕称帝取自汉魏政权更替的历史，民间签题借身份变化表达新局面与责任。"),
        .init(id: 96, title: "窦燕山积善", rank: "上签", palace: "戌宫", poem: "巍峨宝塔不寻常\n八面玲珑尽放光\n劝君立志勤顶礼\n作善苍天降福祥", poeticMeaning: "此卦福德现身之象。凡事大吉利也。", explanation: "这些福份。众人皆见。不用心忙。福德前定。", omens: [.init(subject: "家宅", text: "许愿"), .init(subject: "自身", text: "许经"), .init(subject: "求财", text: "正胜"), .init(subject: "交易", text: "大吉"), .init(subject: "婚姻", text: "好合"), .init(subject: "六甲", text: "喜"), .init(subject: "行人", text: "动"), .init(subject: "田蚕", text: "平稳"), .init(subject: "六畜", text: "欠利"), .init(subject: "寻人", text: "遇"), .init(subject: "公讼", text: "和"), .init(subject: "移徙", text: "吉"), .init(subject: "疾病", text: "禳星"), .init(subject: "山坟", text: "平")], theme: "日常与积累：善意不必求神秘回报，持续行动本身已有意义。", story: "窦燕山教子的民间故事常以积善与教育为线索，不同记述对家庭和年代细节有所差异。"),
        .init(id: 97, title: "六出祁山", rank: "中签", palace: "亥宫", poem: "当风点烛空疏影\n恍惚铺成镜里花\n累被儿竟求牧拾\n怎知只是幻浮槎", poeticMeaning: "此卦当风点烛之象。凡事虚名不利也。", explanation: "富贵在天。贫穷是命。不用求谋。皆是前定。", omens: [.init(subject: "家宅", text: "祈福"), .init(subject: "自身", text: "谨慎"), .init(subject: "求财", text: "得利"), .init(subject: "交易", text: "慎重"), .init(subject: "婚姻", text: "中平"), .init(subject: "六甲", text: "有惊"), .init(subject: "行人", text: "杳"), .init(subject: "田蚕", text: "损"), .init(subject: "六畜", text: "损"), .init(subject: "寻人", text: "无踪"), .init(subject: "公讼", text: "亏"), .init(subject: "移徙", text: "守旧"), .init(subject: "失物", text: "凶"), .init(subject: "疾病", text: "犯阴"), .init(subject: "山坟", text: "改")], theme: "坚持与止损：反复尝试时，也需要检验策略和承受范围。", story: "六出祁山借诸葛亮北伐的文学叙事寄意。次数和情节在史书与演义中并非完全相同。"),
        .init(id: 98, title: "吉平遇难", rank: "下签", palace: "亥宫", poem: "出入求谋事宜迟\n只恐闲愁惹是非\n如鸟飞入罗网内\n脱困能有几多时", poeticMeaning: "此卦守旧随缘之象。凡事不如意主凶也。", explanation: "守旧随时。待贵人至。若问诸般。主事定迟。", omens: [.init(subject: "家宅", text: "忧疑"), .init(subject: "自身", text: "小人"), .init(subject: "求财", text: "破"), .init(subject: "交易", text: "损失"), .init(subject: "婚姻", text: "不长"), .init(subject: "六甲", text: "刑损"), .init(subject: "行人", text: "困"), .init(subject: "田蚕", text: "损"), .init(subject: "六畜", text: "损"), .init(subject: "寻人", text: "杳"), .init(subject: "公讼", text: "亏"), .init(subject: "移徙", text: "勿动"), .init(subject: "失物", text: "凶"), .init(subject: "山坟", text: "绝"), .init(subject: "疾病", text: "犯罗网")], theme: "艰难与底线：处境复杂时，优先照顾安全并寻找合适支持。", story: "吉平遇难取自三国演义中的政治故事，含有舍身情节。本版将其作为文学背景，不鼓励模仿危险行为。"),
        .init(id: 99, title: "陶三春挂帅", rank: "下签", palace: "亥宫", poem: "勒马持鞭直过来\n半有忧危半有灾\n恰似遭火焚烧屋\n天降时雨荡成灰", poeticMeaning: "此卦半忧半喜之象。凡事只宜行善也。", explanation: "终身劳力。莫管是非。枷锁临时。怨尤自至。", omens: [.init(subject: "家宅", text: "祈保"), .init(subject: "自身", text: "守慎"), .init(subject: "求财", text: "破"), .init(subject: "交易", text: "阻"), .init(subject: "婚姻", text: "刑克"), .init(subject: "六甲", text: "险"), .init(subject: "行人", text: "困"), .init(subject: "田蚕", text: "损"), .init(subject: "六畜", text: "损"), .init(subject: "寻人", text: "招非"), .init(subject: "公讼", text: "亏"), .init(subject: "移徙", text: "守旧"), .init(subject: "失物", text: "凶"), .init(subject: "疾病", text: "忧危"), .init(subject: "山坟", text: "败")], theme: "担当与协作：新的责任可以承担，也可以向伙伴说明支持需要。", story: "陶三春挂帅来自宋初题材的民间戏曲，借女将领担任军务表现能力、责任与协作。"),
        .init(id: 100, title: "三教谈道", rank: "下签", palace: "亥宫", poem: "佛神灵通与君知\n痴人说事转昏迷\n老人求得灵签去\n不如守旧待时来", poeticMeaning: "此卦守常勿动之象。凡事宜待时吉也。", explanation: "完满灵签。尽报君知。依旧勿动。待等时至。", omens: [.init(subject: "总述", text: "此是满签。诸事不利。大作佛力。可保平安。")], theme: "多元与自问：不同观点可以并置，最后仍需回到事实与自身选择。", story: "三教谈道是民间文化中的儒释道对话意象，表现不同思想相互参照，并非某一次谈话的史实记录。")
    ]
}
